(window.CLAVE_ARTF=window.CLAVE_ARTF||{})[18]=[["Artículo 2 <span class=\"ex-sello ex-sello-r\">R1</span>","<p><b>1.</b> <mark class=\"m-accion\">No será castigado</mark> ningún <mark class=\"m-personalizado\">delito con pena que no se</mark> halle prevista <span class=\"ex-plg\"><span class=\"ex-plg-t\">por ley <mark class=\"m-destacable\"><u class=\"m-clave\">anterior</u></mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">su</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">perpetración.</u></mark> <mark class=\"m-accion\">Carecerán,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">igualmente, de efecto retroactivo las leyes que establezcan medidas de seguridad.</u></mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-51\">🎯 1 pregunta</mark></p><p data-r=\"R1\"><span class=\"ex-sello ex-sello-r\">R1</span> <b><mark class=\"m-personalizado\"><u class=\"m-clave\">2.</u></mark></b> <mark class=\"m-personalizado\"><u class=\"m-clave\">No obstante,</u></mark> <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">efecto retroactivo aquellas</u></mark> <mark class=\"m-resp\" data-q=\"18-12\">leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena</mark>. En caso de duda sobre la <span class=\"ex-plg\"><span class=\"ex-plg-t\">determinación de la Ley más favorable, <mark class=\"m-accion\">será</mark> oído el <mark class=\"m-personalizado\">reo. Los hechos</mark> cometidos bajo la vigencia de una Ley temporal <mark class=\"m-accion\">serán juzgados,</mark></span></span> sin embargo, <mark class=\"m-personalizado\">conforme</mark> a ella, <mark class=\"m-resp r-ia\" data-q=\"18-ia-1005\">salvo que se disponga expresamente lo contrario</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1004\">🎯 1 pregunta</mark></p>"],["Artículo 4 <span class=\"ex-sello\">✱</span>","<p><b>1.</b> <mark class=\"m-personalizado\">Las leyes penales</mark> <mark class=\"m-accion\">no se aplicarán</mark> a <mark class=\"m-personalizado\">casos distintos de</mark> los <span class=\"ex-plg\"><span class=\"ex-plg-t\">comprendidos <mark class=\"m-personalizado\">expresamente en ellas.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-65,18-187,18-205,18-ia-1008\">🎯 4 preguntas</mark></p><p data-ex=\"*\"><b>2.</b> En el caso de que <span class=\"ex-plg\"><span class=\"ex-plg-t\">un <mark class=\"m-autoridad\">Juez o Tribunal,</mark> en el ejercicio de su jurisdicción, tenga <mark class=\"m-personalizado\">conocimiento</mark> de alguna <mark class=\"m-personalizado\">acción u omisión</mark> que, <mark class=\"m-personalizado\">sin estar penada por la Ley, <u class=\"m-clave\">estime digna</u> de represión,</mark> <mark class=\"m-accion\">se abstendrá</mark> de todo <mark class=\"m-personalizado\">procedimiento</mark> sobre ella <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">expondrá</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-personalizado\">las razones</mark> que le asistan para creer que debiera ser <mark class=\"m-personalizado\">objeto de sanción penal.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-97,18-ia-1009\">🎯 2 preguntas</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">Del mismo modo</mark> <mark class=\"m-accion\">acudirá</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Gobierno</mark> exponiendo <span class=\"ex-plg\"><span class=\"ex-plg-t\">lo conveniente sobre la <mark class=\"m-personalizado\">derogación o modificación</mark> del precepto <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> la concesión <mark class=\"m-personalizado\">de indulto, sin perjuicio de ejecutar desde</mark> luego la <mark class=\"m-personalizado\">sentencia,</mark> cuando <mark class=\"m-personalizado\">de la rigurosa aplicación</mark> de las disposiciones de la Ley resulte penada una <mark class=\"m-personalizado\">acción u omisión que, a juicio del</mark> <mark class=\"m-autoridad\">Juez o Tribunal,</mark> <mark class=\"m-personalizado\">no debiera serlo,</mark> o cuando la pena sea <mark class=\"m-personalizado\">notablemente</mark> <mark class=\"m-destacable\">excesiva,</mark> <mark class=\"m-personalizado\">atendidos el mal causado</mark> por la infracción <mark class=\"m-destacable\">y</mark> <mark class=\"m-personalizado\">las circunstancias personales del reo.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-207,18-ia-1010\">🎯 2 preguntas</mark></p><p><b>4.</b> <mark class=\"m-personalizado\">Si mediara petición</mark> de <mark class=\"m-destacable\">indulto,</mark> y el <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Juez o Tribunal</mark> hubiere <mark class=\"m-personalizado\">apreciado</mark> en resolución fundada que por el <mark class=\"m-personalizado\">cumplimiento</mark> de la pena <mark class=\"m-accion\">puede resultar</mark> <mark class=\"m-personalizado\">vulnerado</mark> el derecho a <mark class=\"m-personalizado\">un proceso <u class=\"m-clave\">sin</u> dilaciones indebidas,</mark> <mark class=\"m-accion\">suspenderá</mark></span></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">la</u></mark> <mark class=\"m-destacable\">ejecución</mark> de la misma <mark class=\"m-resp r-ia\" data-q=\"18-ia-1011\">en tanto no se <mark class=\"m-personalizado\">resuelva sobre la petición</mark> formulada</mark>.</p>"],["Artículo 5","<p><mark class=\"m-personalizado\">No hay pena sin dolo</mark> <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">imprudencia.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-107,18-189,18-ia-1012\">🎯 3 preguntas</mark></p>"],["Artículo 6 <span class=\"ex-sello\">✱</span>","<p><b>1.</b> <mark class=\"m-personalizado\">Las</mark> <mark class=\"m-destacable\">medidas de</mark> seguridad <mark class=\"m-destacable\">se</mark> <mark class=\"m-personalizado\">fundamentan</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en la <mark class=\"m-personalizado\">peligrosidad criminal del sujeto al que se</mark> impongan, <mark class=\"m-personalizado\">exteriorizada en la</mark> <mark class=\"m-autoridad\">comisión</mark> de un <mark class=\"m-personalizado\">hecho</mark> previsto <mark class=\"m-personalizado\">como delito.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-184,18-ia-1013\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-destacable\">Las medidas de seguridad</mark> no <mark class=\"m-personalizado\">pueden resultar ni más gravosas ni de mayor duración</mark> que <mark class=\"m-personalizado\">la pena <u class=\"m-clave\">abstractamente</u> aplicable</mark> al hecho cometido, <mark class=\"m-personalizado\">ni exceder</mark> el límite de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1014\">lo <mark class=\"m-personalizado\">necesario</mark> para <mark class=\"m-personalizado\">prevenir la</mark> peligrosidad del autor</mark>.</p>"],["Artículo 8 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><mark class=\"m-personalizado\">Los hechos</mark> susceptibles de ser <mark class=\"m-personalizado\">calificados</mark> con arreglo a <mark class=\"m-autoridad\">dos o más</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">preceptos de este Código, y no comprendidos</span></span> en los artículos <mark class=\"m-personalizado\">73</mark> a 77, <mark class=\"m-accion\">se castigarán</mark> observando las siguientes <mark class=\"m-destacable\">reglas:</mark> <mark class=\"m-resp ex-q\" data-q=\"18-248\">🎯 1 pregunta</mark></p><p><b>1.ª</b> <mark class=\"m-personalizado\">El</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">precepto</u> especial</mark> <mark class=\"m-accion\">se aplicará</mark> <mark class=\"m-destacable\">con preferencia al general.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-109,18-202,18-ia-1016\">🎯 3 preguntas</mark></p><p><b><mark class=\"m-personalizado\">4.ª</mark></b> <mark class=\"m-personalizado\">En defecto</mark> de <mark class=\"m-personalizado\">los criterios</mark> anteriores, <span class=\"ex-plg\"><span class=\"ex-plg-t\">el precepto penal más <mark class=\"m-personalizado\">grave</mark> <mark class=\"m-accion\">excluirá</mark> <mark class=\"m-personalizado\">los que castiguen el</mark> <mark class=\"m-destacable\">hecho con</mark> pena <mark class=\"m-autoridad\">menor.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1017,18-ia-1018\">🎯 2 preguntas</mark></p>"],["Artículo 9","<p><mark class=\"m-personalizado\">Las disposiciones de <u class=\"m-clave\">este</u> Título</mark> <mark class=\"m-accion\">se aplicarán</mark> a los <mark class=\"m-personalizado\">delitos</mark> que <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">se hallen penados</mark> por <mark class=\"m-personalizado\"><u class=\"m-clave\">leyes</u> <mark class=\"m-resp\" data-q=\"18-216\">especiales</mark>. <u class=\"m-clave\">Las restantes</u> disposiciones</mark> de <mark class=\"m-personalizado\">este Código</mark> <mark class=\"m-accion\">se aplicarán</mark> <mark class=\"m-personalizado\">como supletorias en lo no previsto</mark> expresamente por <mark class=\"m-personalizado\">aquéllas.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1019\">🎯 1 pregunta</mark></p>"],["Artículo 10","<p><mark class=\"m-destacable\">Son delitos</mark> <mark class=\"m-personalizado\">las acciones y omisiones</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">dolosas o imprudentes</u></mark> <mark class=\"m-personalizado\">penadas por la ley.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-37,18-59,18-147,18-ia-1020\">🎯 4 preguntas</mark></p>"],["Artículo 11 <span class=\"ex-sello\">EX</span>","<p><mark class=\"m-personalizado\">Los delitos</mark> <u class=\"m-clave\">que</u> consistan en la producción <span class=\"ex-plg\"><span class=\"ex-plg-t\">de un <mark class=\"m-personalizado\"><u class=\"m-clave\">resultado</u> sólo</mark> <mark class=\"m-accion\">se entenderán</mark> <mark class=\"m-personalizado\">cometidos</mark> por omisión <mark class=\"m-personalizado\">cuando</mark> la no <mark class=\"m-personalizado\">evitación</mark> del mismo, al <mark class=\"m-personalizado\">infringir un especial deber jurídico</mark> del <mark class=\"m-personalizado\">autor,</mark> equivalga, según <mark class=\"m-personalizado\">el sentido</mark> del texto de <mark class=\"m-personalizado\">la ley, a <mark class=\"m-resp r-ia\" data-q=\"18-ia-1021\">su causación</mark>. A tal efecto</mark> <mark class=\"m-accion\">se equiparará</mark> <mark class=\"m-personalizado\">la omisión</mark> a la acción:</span></span></p><p style=\"margin-left:18px\" data-ex=\"EX\"><b>a)</b> Cuando exista una <mark class=\"m-personalizado\"><u class=\"m-clave\">específica</u></mark> <mark class=\"m-autoridad\">obligación</mark> <mark class=\"m-destacable\">legal</mark> o <mark class=\"m-destacable\">contractual</mark> <mark class=\"m-personalizado\">de actuar.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-138\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>b)</b> Cuando el <mark class=\"m-autoridad\">omitente</mark> <mark class=\"m-personalizado\">haya <u class=\"m-clave\">creado una</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\"><u class=\"m-clave\">ocasión</u> de riesgo</mark> <mark class=\"m-personalizado\">para</mark> el <mark class=\"m-personalizado\">bien jurídicamente protegido mediante una acción u omisión</mark> <mark class=\"m-autoridad\">precedente.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1022\">🎯 1 pregunta</mark></p>"],["Artículo 14 <span class=\"ex-sello ex-sello-r\">R4</span> <span class=\"ex-sello ex-sello-r\">R5</span> <span class=\"ex-sello ex-sello-r\">R6</span>","<p data-r=\"R4\"><span class=\"ex-sello ex-sello-r\">R4</span> <b>1.</b> <mark class=\"m-destacable\">El error invencible</mark> <mark class=\"m-personalizado\">sobre un hecho <u class=\"m-clave\">constitutivo de la infracción penal excluye</u> la responsabilidad <u class=\"m-clave\">criminal.</u> Si el error,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">atendidas las circunstancias del hecho y las personales</span></span> del autor, fuera <mark class=\"m-personalizado\"><u class=\"m-clave\">vencible,</u></mark> la infracción <mark class=\"m-accion\">será castigada,</mark> en su caso, <mark class=\"m-personalizado\">como imprudente.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-183\">🎯 1 pregunta</mark></p><p data-ex=\"EXAMEN\" data-r=\"R6\"><span class=\"ex-sello ex-sello-r\">R6</span> <b>3.</b> <mark class=\"m-destacable\">El error invencible</mark> <mark class=\"m-personalizado\">sobre la ilicitud del</mark> hecho constitutivo de la infracción penal <mark class=\"m-personalizado\">excluye</mark> la <mark class=\"m-personalizado\">responsabilidad criminal.</mark> Si el error fuera <mark class=\"m-personalizado\">vencible,</mark> <mark class=\"m-accion\">se aplicará</mark> la <mark class=\"m-personalizado\">pena inferior en uno</mark> <mark class=\"m-destacable\">o dos grados.</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>ERROR (cuadro del temario · art. 14)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Error</span><span>Efecto</span></div><div class=\"vt-nodo\"><div class=\"vt-et o\">DE TIPO (art. 14.1)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Vencible</span><div class=\"vt-t\">Se castiga como imprudente.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Invencible</span><div class=\"vt-t\"><mark class=\"m-plazo\">No existe delito</mark>.</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">DE PROHIBICIÓN (art. 14.3)</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">Vencible</span><div class=\"vt-t\">Se rebaja la pena en uno o dos grados.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">Invencible</span><div class=\"vt-t\"><mark class=\"m-plazo\">No existe delito</mark>.</div></div></div></div></div></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>TENTATIVA · Art. 16 CP (cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">Se produce cuando</span>El sujeto da principio a <mark class=\"m-personalizado\">la ejecución</mark> del <mark class=\"m-personalizado\">delito</mark>: <mark class=\"m-personalizado\">directamente</mark>, y por <mark class=\"m-personalizado\">hechos</mark> exteriores + practica todos o parte de los actos que objetivamente deberían producir el <u class=\"m-clave\">resultado</u> = el <u class=\"m-clave\">resultado</u> del <mark class=\"m-personalizado\">delito</mark> <u class=\"m-clave\">no</u> se produce por causas independientes de la voluntad <mark class=\"m-personalizado\">del autor</mark>.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso v\"><span class=\"et\">Quedará EXENTO de responsabilidad penal quien</span>Evite voluntariamente la consumación del <mark class=\"m-personalizado\">delito</mark>, <mark class=\"m-destacable\">bien</mark>: desistiendo de <mark class=\"m-personalizado\">la ejecución</mark> ya iniciada, <mark class=\"m-destacable\">bien</mark> impidiendo la producción del <u class=\"m-clave\">resultado</u>. <u class=\"m-clave\">Sin perjuicio</u> de <mark class=\"m-personalizado\">la responsabilidad</mark> en que pudiera haber incurrido por los actos ejecutados, <mark class=\"m-personalizado\">si</mark> éstos fueren ya constitutivos de otro <mark class=\"m-personalizado\">delito</mark>.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso c\"><span class=\"et\">Si intervienen varios sujetos</span><mark class=\"m-accion\">Quedarán</mark> exentos de responsabilidad <u class=\"m-clave\">penal</u> aquél o aquéllos que desistan de <mark class=\"m-personalizado\">la ejecución</mark> ya iniciada <mark class=\"m-plazo\">e</mark> impidan o intenten <mark class=\"m-personalizado\">impedir</mark>, <u class=\"m-clave\">seria, firme y decididamente</u>, la consumación. (<u class=\"m-clave\">Sin perjuicio</u> de <mark class=\"m-personalizado\">la responsabilidad</mark> por los actos ejecutados, <mark class=\"m-personalizado\">si</mark> éstos fueren ya constitutivos de otro <mark class=\"m-personalizado\">delito</mark>.)</div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 16: <mark class=\"m-resp ex-q\" data-q=\"18-50,18-95,18-108,18-128,18-ia-1030,18-ia-1031,18-ia-1032\">🎯 7 preguntas más de este artículo</mark>"],["Artículo 17 <span class=\"ex-sello ex-sello-r\">R8</span> <span class=\"ex-sello ex-sello-r\">R9</span> <span class=\"ex-sello ex-sello-r\">R10</span>","<p data-r=\"R8\"><span class=\"ex-sello ex-sello-r\">R8</span> <b>1.</b> <mark class=\"m-destacable\">La conspiración</mark> existe cuando <mark class=\"m-personalizado\">dos o más</mark> <mark class=\"m-autoridad\">personas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">se <u class=\"m-clave\">conciertan</u> para la ejecución de un delito y resuelven ejecutarlo.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1033\">🎯 1 pregunta</mark></p><p data-r=\"R9\"><span class=\"ex-sello ex-sello-r\">R9</span> <b>2.</b> <mark class=\"m-destacable\">La proposición</mark> existe cuando <mark class=\"m-personalizado\">el que ha resuelto</mark> cometer <span class=\"ex-plg\"><span class=\"ex-plg-t\">un delito <mark class=\"m-personalizado\">invita</mark> a otra u otras <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">a participar</mark> en <mark class=\"m-personalizado\">él.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-250,18-ia-1034\">🎯 2 preguntas</mark></p><p data-r=\"R10\"><span class=\"ex-sello ex-sello-r\">R10</span> <b>3.</b> La conspiración y la proposición <span class=\"ex-plg\"><span class=\"ex-plg-t\">para delinquir <mark class=\"m-personalizado\">sólo</mark> <mark class=\"m-accion\">se castigarán</mark> en los <mark class=\"m-personalizado\">casos especialmente previstos en la ley.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1035\">🎯 1 pregunta</mark></p>"],["Artículo 18 <span class=\"ex-sello ex-sello-r\">R11</span> <span class=\"ex-sello ex-sello-r\">R12</span> <span class=\"ex-sello ex-sello-r\">R13</span>","<p data-r=\"R11\"><span class=\"ex-sello ex-sello-r\">R11</span> <b>1.</b> <mark class=\"m-destacable\">La provocación</mark> existe cuando <mark class=\"m-personalizado\">directamente <u class=\"m-clave\">se</u> incita</mark> por <span class=\"ex-plg\"><span class=\"ex-plg-t\">medio de <mark class=\"m-personalizado\">la imprenta, la <u class=\"m-clave\">radiodifusión o</u> cualquier otro medio de eficacia semejante,</mark> que facilite la publicidad, <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u> ante una <u class=\"m-clave\">concurrencia</u> de</mark> <mark class=\"m-autoridad\">personas,</mark> <mark class=\"m-personalizado\">a la perpetración</mark> de <mark class=\"m-personalizado\">un delito.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1036\">🎯 1 pregunta</mark></p><p data-r=\"R12\"><span class=\"ex-sello ex-sello-r\">R12</span> <mark class=\"m-destacable\">Es apología,</mark> a los efectos de este <span class=\"ex-plg\"><span class=\"ex-plg-t\">Código, <mark class=\"m-personalizado\"><u class=\"m-clave\">la</u> exposición, ante</mark> una <mark class=\"m-personalizado\">concurrencia de</mark> <mark class=\"m-autoridad\">personas</mark> o por <mark class=\"m-personalizado\">cualquier <u class=\"m-clave\">medio de</u> difusión, de ideas o doctrinas <u class=\"m-clave\">que ensalcen</u> el crimen o enaltezcan a su autor. La apología sólo</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">delictiva</u> como forma</mark> de provocación y si por su naturaleza y circunstancias constituye <mark class=\"m-personalizado\">una <u class=\"m-clave\">incitación</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">directa</mark></span> <mark class=\"m-personalizado\">a cometer</mark> un delito.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-165,18-ia-1037\">🎯 2 preguntas</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">La provocación</mark> <mark class=\"m-accion\">se castigará</mark> exclusivamente <mark class=\"m-personalizado\">en los casos en que la Ley así lo prevea.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-118\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>CONSPIRACIÓN · PROPOSICIÓN · PROVOCACIÓN (cuadro del temario · arts. 17 y 18)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>CONSPIRACIÓN</h5><ul><li><mark class=\"m-personalizado\">Dos o más</mark> <mark class=\"m-autoridad\">personas</mark> se <u class=\"m-clave\">conciertan</u> y resuelven ejecutar <mark class=\"m-personalizado\">un delito</mark>.</li></ul></div><div class=\"vis-col\"><h5>PROPOSICIÓN</h5><ul><li><mark class=\"m-personalizado\">El que ha resuelto</mark> cometer <mark class=\"m-personalizado\">un delito</mark> <mark class=\"m-personalizado\">invita</mark> a otro/s <mark class=\"m-personalizado\">a participar</mark> en <mark class=\"m-personalizado\">él</mark>.</li></ul></div><div class=\"vis-col\"><h5>PROVOCACIÓN</h5><ul><li>Se incita a otro/s a que cometan <mark class=\"m-personalizado\">un delito</mark>.</li></ul></div>"],["Artículo 20 <span class=\"ex-sello\">EX</span>","<p><b>1.º</b> <mark class=\"m-personalizado\">El que <u class=\"m-clave\">al</u> tiempo de cometer</mark> la infracción penal, <mark class=\"m-personalizado\">a causa</mark> de cualquier <mark class=\"m-destacable\">anomalía o alteración psíquica,</mark> <mark class=\"m-personalizado\">no pueda <u class=\"m-clave\">comprender</u></mark> la ilicitud del hecho <mark class=\"m-personalizado\">o actuar conforme</mark> a esa comprensión. <mark class=\"m-resp ex-q\" data-q=\"18-19,18-ia-1040\">🎯 2 preguntas</mark></p><p><mark class=\"m-personalizado\">El trastorno mental transitorio</mark> <mark class=\"m-accion\">no eximirá</mark> de pena cuando <span class=\"ex-plg\"><span class=\"ex-plg-t\">hubiese sido <mark class=\"m-personalizado\">provocado</mark> por el sujeto <mark class=\"m-personalizado\">con el propósito de cometer</mark> el delito o hubiera previsto o debido prever su <mark class=\"m-autoridad\">comisión.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1041\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.º</b> <mark class=\"m-personalizado\">El que al tiempo de cometer</mark> la infracción penal se halle en <mark class=\"m-personalizado\">estado de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">intoxicación</u> plena</mark> por el <mark class=\"m-personalizado\">consumo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de bebidas alcohólicas, drogas tóxicas, estupefacientes, sustancias psicotrópicas u otras</span></span> que produzcan efectos <mark class=\"m-personalizado\">análogos, siempre que no haya sido buscado</mark> con el <mark class=\"m-personalizado\">propósito</mark> de cometerla <mark class=\"m-personalizado\">o</mark> no se hubiese <mark class=\"m-personalizado\">previsto o debido prever su</mark> <mark class=\"m-autoridad\">comisión,</mark> <mark class=\"m-personalizado\">o</mark> se halle bajo la influencia de un <mark class=\"m-personalizado\">síndrome de abstinencia, <u class=\"m-clave\">a</u></mark> causa de su <mark class=\"m-personalizado\">dependencia</mark> de tales sustancias, <mark class=\"m-personalizado\"><u class=\"m-clave\">que le</u> impida <u class=\"m-clave\">comprender la ilicitud</u> del</mark> hecho <mark class=\"m-personalizado\"><u class=\"m-clave\">o actuar conforme</u></mark> a esa comprensión. <mark class=\"m-resp ex-q\" data-q=\"18-62,18-ia-1042,18-ia-1043\">🎯 3 preguntas</mark></p><p><b>3.º</b> El que, por sufrir <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">alteraciones en la percepción <u class=\"m-clave\">desde el nacimiento o desde la infancia, tenga</u> alterada <u class=\"m-clave\">gravemente</u> la conciencia de la realidad.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1044\">🎯 1 pregunta</mark></p><p><b>Primero.</b> Agresión ilegítima. En caso de defensa de los bienes <mark class=\"m-accion\">se reputará</mark> agresión ilegítima el <mark class=\"m-resp\" data-q=\"18-224,18-ia-1047\">ataque a los mismos que constituya delito y los ponga en grave peligro de deterioro o pérdida inminentes</mark>. En caso de defensa de la morada o sus dependencias, <mark class=\"m-accion\">se reputará</mark> agresión ilegítima la <mark class=\"m-resp\" data-q=\"18-238,18-ia-1046\">entrada indebida en aquélla o éstas</mark>.</p><p><b>Segundo.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Necesidad racional del medio empleado para impedirla o repelerla.</span></span> <mark class=\"m-resp ex-q\" data-q=\"18-76\">🎯 1 pregunta</mark></p><p><b>Primero.</b> <mark class=\"m-resp\" data-q=\"18-68\">Que el <mark class=\"m-destacable\">mal causado no sea mayor</mark> que el que se trate de evitar</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1045\">🎯 1 pregunta</mark></p><p><b>Segundo.</b> <mark class=\"m-resp\" data-q=\"18-175\">Que la situación de <mark class=\"m-personalizado\">necesidad</mark> no <mark class=\"m-destacable\">haya sido provocada intencionadamente</mark> por el sujeto</mark>.</p><p><b>Tercero.</b> Que el necesitado <mark class=\"m-destacable\">no tenga, por su oficio o cargo,</mark> <mark class=\"m-personalizado\">obligación de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1049\">sacrificarse</mark>.</mark></p><p><b>6.º</b> El que obre impulsado por <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1050\">miedo insuperable</mark>.</mark></p><p><b>7.º</b> El que obre en <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">cumplimiento de un deber</mark> <mark class=\"m-personalizado\">o en el</mark> <mark class=\"m-destacable\">ejercicio legítimo</mark> <mark class=\"m-personalizado\">de un derecho, oficio</mark> o <mark class=\"m-destacable\">cargo.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1051\">🎯 1 pregunta</mark></p><p>En los supuestos de los <mark class=\"m-personalizado\">tres</mark> primeros <mark class=\"m-personalizado\">números</mark> <mark class=\"m-accion\">se aplicarán,</mark> en su caso, las <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1052\">medidas de seguridad previstas en este Código</mark>.</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>REQUISITOS DE LA LEGÍTIMA DEFENSA (cuadro del temario · art. 20.4)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>1.º Agresión ilegítima</h5><ul><li>Defensa <mark class=\"m-personalizado\">de los bienes</mark>: el ataque que constituya <mark class=\"m-personalizado\">delito</mark> y los ponga en <mark class=\"m-personalizado\">grave</mark> peligro de deterioro o pérdida inminentes.</li><li>Defensa de la morada o sus dependencias: la entrada indebida en aquélla o éstas.</li></ul></div><div class=\"vis-col\"><h5>2.º Necesidad racional del medio empleado</h5><ul><li>Para impedirla o repelerla.</li></ul></div><div class=\"vis-col\"><h5>3.º Falta de provocación suficiente</h5><ul><li>Por parte del <mark class=\"m-autoridad\">defensor</mark>.</li></ul></div>"],["Artículo 21 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p><b>1.ª</b> Las causas expresadas en <span class=\"ex-plg\"><span class=\"ex-plg-t\">el <mark class=\"m-personalizado\">capítulo anterior,</mark> <mark class=\"m-destacable\">cuando no concurrieren todos los requisitos</mark> necesarios para eximir de responsabilidad en sus respectivos casos.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1053\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.ª</b> <mark class=\"m-personalizado\">La de actuar</mark> el culpable a causa de <mark class=\"m-personalizado\">su</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">grave adicción</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">a las sustancias mencionadas en el número 2.º del artículo anterior.</span></span> <mark class=\"m-resp ex-q\" data-q=\"18-129,18-ia-1054\">🎯 2 preguntas</mark></p><p><b>3.ª</b> <mark class=\"m-personalizado\">La de obrar</mark> por causas o estímulos <mark class=\"m-personalizado\">tan poderosos</mark> que hayan producido <mark class=\"m-destacable\">arrebato, obcecación</mark> u <mark class=\"m-personalizado\">otro</mark> <mark class=\"m-destacable\">estado pasional</mark> <mark class=\"m-personalizado\">de entidad semejante.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-218,18-ia-1055\">🎯 2 preguntas</mark></p><p><b>4.ª</b> La de <mark class=\"m-personalizado\">haber procedido</mark> el <span class=\"ex-plg\"><span class=\"ex-plg-t\">culpable, <mark class=\"m-destacable\">antes de conocer</mark> que el <mark class=\"m-personalizado\">procedimiento judicial se dirige contra él, a <u class=\"m-clave\">confesar</u></mark> la infracción <mark class=\"m-personalizado\">a las</mark> <mark class=\"m-autoridad\">autoridades.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1056\">🎯 1 pregunta</mark></p><p><b><mark class=\"m-personalizado\">5.ª</mark></b> <mark class=\"m-personalizado\">La de haber procedido el culpable a reparar el daño ocasionado a la víctima, o disminuir</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">sus efectos, en cualquier momento del procedimiento y con anterioridad a la celebración</span></span> del acto del <mark class=\"m-personalizado\">juicio oral.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-157,18-ia-1057\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b><mark class=\"m-personalizado\">6.ª</mark></b> <mark class=\"m-personalizado\">La dilación extraordinaria e indebida en la tramitación del procedimiento, siempre que no sea atribuible</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">al propio inculpado y que no guarde proporción con la complejidad de la causa.</span></span> <mark class=\"m-resp ex-q\" data-q=\"18-100,18-170,18-179,18-ia-1058\">🎯 4 preguntas</mark></p>"],["Artículo 22 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.ª</b> Ejecutar el hecho con <mark class=\"m-autoridad\">alevosía.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-9\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Hay alevosía cuando el culpable comete cualquiera de los delitos contra las</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">empleando en</mark> la ejecución medios, modos o formas que <mark class=\"m-personalizado\">tiendan directa o especialmente a asegurarla, sin</mark> el riesgo que para su <mark class=\"m-autoridad\">persona</mark> pudiera proceder de la <mark class=\"m-resp r-ia\" data-q=\"18-ia-1059\">defensa por parte del ofendido</mark>. <mark class=\"m-resp ex-q\" data-q=\"18-131,18-196\">🎯 2 preguntas</mark></p><p><b>2.ª</b> <mark class=\"m-resp\" data-q=\"18-106,18-ia-1060\">Ejecutar el hecho mediante disfraz, con abuso <mark class=\"m-personalizado\">de superioridad o aprovechando las circunstancias de lugar, tiempo o auxilio de otras</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">que debiliten la defensa del ofendido o faciliten la impunidad</mark> del delincuente</mark>. <mark class=\"m-resp ex-q\" data-q=\"18-215\">🎯 1 pregunta</mark></p><p><b>3.ª</b> Ejecutar el hecho <mark class=\"m-personalizado\">mediante</mark> <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1061\">precio, recompensa o promesa</mark>.</mark></p><p><b>4.ª</b> Cometer el delito <mark class=\"m-personalizado\">por</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">motivos racistas, antisemitas,</mark> antigitanos <mark class=\"m-personalizado\">u</mark> <mark class=\"m-autoridad\">otra clase de discriminación</mark> referente a la ideología, religión o creencias de la víctima, la etnia, raza o nación a la que pertenezca, su sexo, edad, orientación o identidad sexual o de género, razones de género, de aporofobia o de exclusión social, la enfermedad que padezca o su discapacidad, con independencia de que tales condiciones o circunstancias concurran efectivamente en la <mark class=\"m-autoridad\">persona</mark> sobre la que recaiga la conducta.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1062\">🎯 1 pregunta</mark></p><p><b>5.ª</b> Aumentar deliberada e inhumanamente <span class=\"ex-plg\"><span class=\"ex-plg-t\">el sufrimiento de <mark class=\"m-destacable\">la víctima, causando a ésta padecimientos innecesarios para</mark> la ejecución del delito.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1063\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Hay reincidencia</mark> cuando, al delinquir, <mark class=\"m-personalizado\">el</mark> culpable <mark class=\"m-personalizado\">haya</mark> <mark class=\"m-autoridad\">sido condenado ejecutoriamente</mark> por un <mark class=\"m-personalizado\">delito</mark> comprendido en <mark class=\"m-personalizado\">el <u class=\"m-clave\">mismo título</u></mark> de este código, <mark class=\"m-personalizado\">siempre que sea <mark class=\"m-resp r-ia\" data-q=\"18-ia-1064\">de la misma naturaleza</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-148\">🎯 1 pregunta</mark></p><p>A los efectos de este <span class=\"ex-plg\"><span class=\"ex-plg-t\">número <mark class=\"m-accion\">no se computarán</mark> los antecedentes penales <mark class=\"m-personalizado\">cancelados</mark> o que <mark class=\"m-personalizado\">debieran serlo, ni los que correspondan a</mark> delitos leves, salvo lo dispuesto para los tipos agravados por multirreincidencia de <mark class=\"m-personalizado\"><u class=\"m-clave\">delitos leves.</u></mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1065\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Las condenas firmes de</mark> <mark class=\"m-autoridad\">jueces o tribunales</mark> <mark class=\"m-personalizado\">impuestas</mark> en otros <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-personalizado\">de la Unión Europea</mark> <mark class=\"m-accion\">producirán</mark> los efectos <mark class=\"m-personalizado\">de reincidencia <u class=\"m-clave\">salvo</u></mark> que el antecedente penal <mark class=\"m-personalizado\">haya sido cancelado <u class=\"m-clave\">o</u> pudiera serlo</mark> con arreglo al Derecho español.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1066\">🎯 1 pregunta</mark></p>"],["Artículo 24 <span class=\"ex-sello ex-sello-r\">R14</span>","<p data-r=\"R14\"><span class=\"ex-sello ex-sello-r\">R14</span> <b>1.</b> A los efectos penales <mark class=\"m-accion\">se reputará</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-destacable\">al que por sí solo o como miembro de alguna corporación,</mark> <mark class=\"m-autoridad\">tribunal u órgano colegiado</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1068\">tenga mando o ejerza jurisdicción propia</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">En todo caso, <mark class=\"m-accion\">tendrán</mark> la <mark class=\"m-personalizado\">consideración</mark> de <mark class=\"m-autoridad\">autoridad los miembros del Congreso de los Diputados, del Senado, de las Asambleas Legislativas de las Comunidades Autónomas y del Parlamento Europeo.</mark> <mark class=\"m-accion\">Tendrán también la consideración de autoridad</mark> los <mark class=\"m-autoridad\">funcionarios del Ministerio Fiscal y los Fiscales de la Fiscalía Europea.</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"18-217,18-ia-1069\">🎯 2 preguntas</mark></p><p><b>2.</b> <mark class=\"m-accion\">Se considerará</mark> <mark class=\"m-personalizado\">funcionario público</mark> todo el que <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">por disposición inmediata de la Ley</mark> o <mark class=\"m-personalizado\">por elección</mark> o por nombramiento de <mark class=\"m-autoridad\">autoridad competente</mark> <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1070\">participe en el ejercicio de funciones públicas</mark>.</mark></span></span></p>"],["Artículo 26","<p>A los efectos de este Código <span class=\"ex-plg\"><span class=\"ex-plg-t\">se considera <mark class=\"m-destacable\">documento todo soporte material que exprese o incorpore</mark> <mark class=\"m-personalizado\">datos, hechos o narraciones con eficacia probatoria o</mark> cualquier otro tipo de <mark class=\"m-personalizado\">relevancia jurídica.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-119,18-227,18-ia-1073\">🎯 3 preguntas</mark></p>"],["Artículo 28 <span class=\"ex-sello ex-sello-r\">R15</span> <span class=\"ex-sello ex-sello-r\">R16</span>","<p data-r=\"R15\"><span class=\"ex-sello ex-sello-r\">R15</span> Son <mark class=\"m-destacable\">autores</mark> quienes <mark class=\"m-personalizado\">realizan el hecho por sí solos, conjuntamente o</mark> por <mark class=\"m-personalizado\">medio de otro</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">del que se sirven como <mark class=\"m-personalizado\"><u class=\"m-clave\">instrumento.</u></mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-56,18-126,18-204,18-206,18-ia-1102\">🎯 5 preguntas</mark></p>"],["Artículo 29 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\">Son <mark class=\"m-destacable\">cómplices</mark> los que, no <mark class=\"m-personalizado\">hallándose comprendidos</mark> en el artículo anterior, <mark class=\"m-personalizado\"><u class=\"m-clave\">cooperan a</u> la ejecución del hecho con actos <mark class=\"m-resp r-ia\" data-q=\"18-ia-1105\">anteriores <u class=\"m-clave\">o</u> simultáneos</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-252\">🎯 1 pregunta</mark></p>"],["Artículo 30 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> En los <mark class=\"m-destacable\">delitos</mark> que se <span class=\"ex-plg\"><span class=\"ex-plg-t\">cometan <mark class=\"m-destacable\">utilizando <u class=\"m-clave\">medios</u></mark> o <mark class=\"m-destacable\">soportes de <u class=\"m-clave\">difusión</u> mecánicos</mark> <mark class=\"m-accion\">no responderán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">criminalmente</u> ni los cómplices ni quienes los hubieren favorecido personal</mark> o <mark class=\"m-personalizado\">realmente.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-14,18-113,18-ia-1106\">🎯 3 preguntas</mark></p><p><b>2.</b> Los autores a los que se refiere el artículo 28 <mark class=\"m-accion\">responderán</mark> de <mark class=\"m-personalizado\">forma <mark class=\"m-resp r-ia\" data-q=\"18-ia-1107\">escalonada, excluyente y subsidiaria</mark> de acuerdo con el siguiente orden:</mark></p><p><b>1.º</b> Los que realmente hayan <mark class=\"m-personalizado\">redactado el texto</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o <mark class=\"m-personalizado\">producido el signo</mark> de que se trate, y quienes les <mark class=\"m-personalizado\">hayan inducido a realizarlo.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-91,18-ia-1108\">🎯 2 preguntas</mark></p><p><b>3.º</b> <mark class=\"m-autoridad\">Los directores</mark> <mark class=\"m-personalizado\">de</mark> la <mark class=\"m-personalizado\">empresa editora, emisora o difusora.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1109\">🎯 1 pregunta</mark></p><p><b>4.º</b> <mark class=\"m-autoridad\">Los directores</mark> <mark class=\"m-personalizado\">de la empresa grabadora, reproductora o impresora.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-137\">🎯 1 pregunta</mark></p><p><b>3.</b> Cuando por cualquier motivo distinto <span class=\"ex-plg\"><span class=\"ex-plg-t\">de la extinción de la responsabilidad penal, incluso la declaración de rebeldía o la residencia fuera de España, no pueda perseguirse a ninguna de las <mark class=\"m-autoridad\">personas</mark> comprendidas en alguno de los números del apartado anterior,</span></span> <mark class=\"m-accion\">se dirigirá</mark> el procedimiento contra las <mark class=\"m-resp r-ia\" data-q=\"18-ia-1111\">mencionadas en el número inmediatamente posterior</mark>.</p>"],["Artículo 31 bis","<p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-personalizado\">De los delitos cometidos en nombre <u class=\"m-clave\">o</u> por cuenta de las mismas, <u class=\"m-clave\">y</u> en su beneficio directo o indirecto, <u class=\"m-clave\">por sus</u> representantes</mark> legales <mark class=\"m-personalizado\">o</mark> por aquellos <span class=\"ex-plg\"><span class=\"ex-plg-t\">que <mark class=\"m-accion\">actuando</mark> <mark class=\"m-autoridad\">individualmente</mark> o como <mark class=\"m-autoridad\">integrantes de un órgano</mark> de la <mark class=\"m-autoridad\">persona</mark> jurídica, <mark class=\"m-accion\">están</mark> <mark class=\"m-personalizado\">autorizados para tomar decisiones</mark> en nombre de la <mark class=\"m-autoridad\">persona</mark> jurídica <mark class=\"m-destacable\">u</mark> ostentan <mark class=\"m-personalizado\">facultades de organización y control</mark> dentro de la misma.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-223,18-ia-1113\">🎯 2 preguntas</mark></p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-personalizado\">De los delitos cometidos, en el ejercicio de actividades sociales</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">por cuenta</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">en beneficio directo o indirecto</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de las mismas, <mark class=\"m-personalizado\">por quienes,</mark> estando <mark class=\"m-personalizado\">sometidos a la</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">de las</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">físicas</mark> mencionadas en el párrafo anterior, han podido realizar los hechos por haberse <mark class=\"m-personalizado\">incumplido <u class=\"m-clave\">gravemente</u></mark> por aquéllos los <mark class=\"m-personalizado\">deberes de supervisión, vigilancia <u class=\"m-clave\">y</u> control de</mark> su <mark class=\"m-personalizado\">actividad</mark> atendidas <mark class=\"m-personalizado\">las</mark> concretas circunstancias del caso.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1114\">🎯 1 pregunta</mark></p><p><b>1.ª</b> <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">de administración ha adoptado y ejecutado con eficacia, <u class=\"m-clave\">antes de la</u></mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">del delito, modelos de organización y gestión</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que incluyen las <mark class=\"m-personalizado\">medidas de vigilancia</mark> y <mark class=\"m-personalizado\">control</mark> idóneas para prevenir delitos de la misma naturaleza <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u> para reducir</mark> de forma significativa el <mark class=\"m-personalizado\">riesgo</mark> de su <mark class=\"m-autoridad\">comisión;</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-130,18-ia-1115\">🎯 2 preguntas</mark></p><p><b>2.ª</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">la</u> supervisión</mark> del funcionamiento y del <span class=\"ex-plg\"><span class=\"ex-plg-t\">cumplimiento del <mark class=\"m-personalizado\">modelo de prevención implantado ha sido confiada a <u class=\"m-clave\">un</u></mark> <mark class=\"m-autoridad\">órgano</mark> de la <mark class=\"m-autoridad\">persona</mark> jurídica <mark class=\"m-personalizado\">con poderes autónomos de iniciativa y de control</mark> o que tenga encomendada legalmente la función de <mark class=\"m-personalizado\">supervisar</mark> la <mark class=\"m-personalizado\">eficacia</mark> de los controles internos de la <mark class=\"m-autoridad\">persona</mark> jurídica;</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1116,18-ia-1117\">🎯 2 preguntas</mark></p><p>En los casos en los que <span class=\"ex-plg\"><span class=\"ex-plg-t\">las <mark class=\"m-personalizado\">anteriores circunstancias</mark> solamente puedan ser objeto de <mark class=\"m-personalizado\">acreditación parcial,</mark> esta circunstancia</span></span> <mark class=\"m-accion\">será valorada</mark> a los efectos de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1118\">atenuación de la pena</mark>.</p><p><b>3.</b> En las <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas de pequeñas dimensiones,</mark> las <span class=\"ex-plg\"><span class=\"ex-plg-t\">funciones de <mark class=\"m-personalizado\">supervisión</mark> a que se refiere la condición 2.ª del apartado 2 <mark class=\"m-accion\">podrán ser asumidas</mark> <mark class=\"m-personalizado\">directamente</mark> por <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">de administración.</mark> A estos efectos, son <mark class=\"m-autoridad\">personas</mark> jurídicas de <mark class=\"m-personalizado\">pequeñas dimensiones</mark> aquéllas que, según la legislación aplicable, <mark class=\"m-personalizado\">estén autorizadas a presentar <u class=\"m-clave\">cuenta</u> de pérdidas y <u class=\"m-clave\">ganancias abreviada.</u></mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1119\">🎯 1 pregunta</mark></p><p><b>4.</b> Si el delito fuera <mark class=\"m-personalizado\">cometido</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">por las <mark class=\"m-autoridad\">personas</mark> indicadas en la letra b) <mark class=\"m-personalizado\">del apartado</mark> 1, la <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">jurídica</mark> <mark class=\"m-accion\">quedará</mark> <mark class=\"m-personalizado\">exenta</mark> de responsabilidad <mark class=\"m-personalizado\"><u class=\"m-clave\">si,</u> antes</mark> de la <mark class=\"m-autoridad\">comisión</mark> del delito, <mark class=\"m-personalizado\">ha adoptado y ejecutado eficazmente</mark> un <mark class=\"m-personalizado\">modelo de organización y gestión</mark> que resulte <mark class=\"m-personalizado\">adecuado para prevenir</mark> delitos de la naturaleza del que fue cometido o <mark class=\"m-personalizado\">para reducir</mark> de forma significativa <mark class=\"m-personalizado\">el riesgo de</mark> su <mark class=\"m-autoridad\">comisión.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1120\">🎯 1 pregunta</mark></p><p><b>6.º</b> <mark class=\"m-accion\">Realizarán</mark> una <mark class=\"m-personalizado\"><u class=\"m-clave\">verificación periódica</u> del modelo</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">su eventual <mark class=\"m-personalizado\">modificación</mark> cuando se pongan de manifiesto infracciones relevantes de sus disposiciones,</span></span> o cuando se produzcan cambios <mark class=\"m-resp r-ia\" data-q=\"18-ia-1122\">en la organización, en la estructura de control o en la actividad desarrollada que los hagan necesarios</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 31 ter: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1123,18-ia-1124\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 31 quinquies <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> <mark class=\"m-destacable\">Las disposiciones</mark> relativas a la responsabilidad <span class=\"ex-plg\"><span class=\"ex-plg-t\">penal de las <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas</mark> <mark class=\"m-accion\">no serán</mark> <mark class=\"m-destacable\">aplicables</mark> <mark class=\"m-autoridad\">al Estado, a las Administraciones públicas territoriales e institucionales, a los Organismos Reguladores, las Agencias y Entidades públicas Empresariales, a las organizaciones internacionales de derecho público, ni a aquellas otras que ejerzan potestades públicas de soberanía o administrativas.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-4,18-144,18-ia-1127\">🎯 3 preguntas</mark></p>"],["Artículo 32","<p><mark class=\"m-personalizado\">Las penas que pueden imponerse</mark> con arreglo a este Código, bien <mark class=\"m-personalizado\">con carácter principal</mark> bien como <mark class=\"m-personalizado\">accesorias, son privativas de libertad, privativas de otros derechos</mark> y <mark class=\"m-personalizado\">multa.</mark>  <mark class=\"m-resp ex-q\" data-q=\"18-242,18-ia-1129\">🎯 2 preguntas</mark></p>"],["Artículo 33 <span class=\"ex-sello\">✱</span>","<p data-ex=\"EXAMEN\"><b>1.</b> En función de su <mark class=\"m-personalizado\">naturaleza y duración,</mark> las penas se clasifican en <mark class=\"m-resp\" data-q=\"18-117,18-ia-1130\">graves, menos graves y leves</mark>.</p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-personalizado\">La prisión <u class=\"m-clave\">superior</u> a cinco años.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1131\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>d)</b> <mark class=\"m-personalizado\">Las inhabilitaciones especiales</mark> por tiempo <mark class=\"m-personalizado\">superior a cinco años.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-77,18-229\">🎯 2 preguntas</mark></p><p style=\"margin-left:18px\"><b>e)</b> <mark class=\"m-personalizado\">La suspensión de empleo o cargo</mark> público por tiempo <mark class=\"m-personalizado\">superior a cinco años.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-111\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>f)</b> <mark class=\"m-personalizado\">La privación del derecho a conducir</mark> vehículos a motor y ciclomotores por tiempo <mark class=\"m-personalizado\">superior</mark> a <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1133\">ocho años</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-201\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>g)</b> La privación del derecho a <mark class=\"m-personalizado\">la tenencia y porte de armas</mark> por tiempo <mark class=\"m-personalizado\">superior a ocho</mark> años. <mark class=\"m-resp ex-q\" data-q=\"18-254\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>h)</b> La privación del <mark class=\"m-personalizado\">derecho a residir</mark> en determinados lugares <mark class=\"m-personalizado\">o acudir</mark> a ellos, por tiempo <mark class=\"m-personalizado\">superior a cinco años.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-244\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>k)</b> <mark class=\"m-personalizado\">La <mark class=\"m-resp\" data-q=\"18-219\">privación de la patria potestad</mark>.</mark></p><p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-personalizado\">La prisión de <u class=\"m-clave\">tres meses</u> hasta cinco años.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1135\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>d)</b> La privación <mark class=\"m-personalizado\">del derecho a conducir</mark> vehículos a motor y ciclomotores <mark class=\"m-personalizado\">de un año</mark> y <mark class=\"m-personalizado\"><u class=\"m-clave\">un</u> día a ocho años.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-255,18-ia-1136\">🎯 2 preguntas</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>e)</b> La <mark class=\"m-resp\" data-q=\"18-99\">privación del derecho a la <mark class=\"m-personalizado\">tenencia y porte de armas de un año y un día</mark> <mark class=\"m-destacable\">a</mark> ocho años</mark>.</p><p style=\"margin-left:18px\" data-ex=\"*\"><b>f)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Inhabilitación</u> especial</mark> para el <mark class=\"m-personalizado\">ejercicio de profesión, oficio o comercio</mark> que tenga relación <mark class=\"m-personalizado\">con los <u class=\"m-clave\">animales y para</u> la tenencia</mark> de animales <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"18-256\">de un año y un día a cinco años</mark>.</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>g)</b> La privación del <mark class=\"m-personalizado\">derecho a residir</mark> en determinados lugares <mark class=\"m-personalizado\">o acudir a</mark> ellos, por tiempo de <mark class=\"m-personalizado\">seis meses a cinco años.</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>h)</b> <mark class=\"m-personalizado\">La prohibición de aproximarse a</mark> la víctima o a aquellos de sus familiares u otras <mark class=\"m-autoridad\">personas</mark> que determine el <mark class=\"m-autoridad\">juez o tribunal,</mark> por tiempo de <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"18-257\">seis meses a cinco años</mark>.</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>i)</b> <mark class=\"m-personalizado\">La prohibición de comunicarse</mark> con la víctima o con aquellos de sus familiares u otras <mark class=\"m-autoridad\">personas</mark> que determine el <mark class=\"m-autoridad\">juez o tribunal,</mark> por tiempo <mark class=\"m-personalizado\">de <mark class=\"m-resp\" data-q=\"18-258,18-ia-1139\">seis meses <u class=\"m-clave\">a cinco</u> años</mark>.</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>j)</b> <mark class=\"m-personalizado\">La multa de <u class=\"m-clave\">más</u> de <u class=\"m-clave\">tres meses.</u></mark> <mark class=\"m-resp ex-q\" data-q=\"18-259,18-ia-1138\">🎯 2 preguntas</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b><mark class=\"m-personalizado\">k)</mark></b> <mark class=\"m-personalizado\">La <u class=\"m-clave\">multa</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">proporcional,</mark></span> <mark class=\"m-personalizado\">cualquiera que fuese su cuantía,</mark> salvo lo dispuesto en el apartado 7 de este artículo. <mark class=\"m-resp ex-q\" data-q=\"18-260\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b><mark class=\"m-personalizado\">l)</mark></b> <mark class=\"m-personalizado\">Los trabajos en beneficio</mark> de la comunidad de <mark class=\"m-personalizado\">treinta</mark> y <mark class=\"m-personalizado\">un días a <u class=\"m-clave\">un</u> año.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1137\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>a)</b> La privación del <mark class=\"m-personalizado\">derecho</mark> a <mark class=\"m-personalizado\">conducir</mark> vehículos a motor y ciclomotores <mark class=\"m-personalizado\">de <u class=\"m-clave\">tres</u> meses a un</mark> año.  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1141\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>d)</b> <mark class=\"m-personalizado\">La privación del derecho a residir</mark> en determinados lugares <mark class=\"m-personalizado\">o acudir</mark> a ellos, por tiempo <mark class=\"m-personalizado\">inferior</mark> a <mark class=\"m-personalizado\">seis</mark> meses.  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1143\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>e)</b> La <mark class=\"m-personalizado\">prohibición</mark> de <mark class=\"m-personalizado\">aproximarse</mark> a la víctima o a aquellos de sus familiares u otras <mark class=\"m-autoridad\">personas</mark> que determine el <mark class=\"m-autoridad\">juez o tribunal,</mark> por tiempo <mark class=\"m-personalizado\">de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1142\">un mes a menos de seis meses</mark>.</mark></p><p style=\"margin-left:18px\"><b>h)</b> La <mark class=\"m-personalizado\">localización permanente de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1140\">un día a tres meses</mark>.</mark></p><p><b>5.</b> <mark class=\"m-destacable\">La responsabilidad personal subsidiaria</mark> <mark class=\"m-personalizado\">por</mark> <mark class=\"m-destacable\">impago de multa</mark> <mark class=\"m-accion\">tendrá</mark> naturaleza <mark class=\"m-personalizado\"><u class=\"m-clave\">menos</u></mark> grave o leve, según la que corresponda a la <mark class=\"m-personalizado\"><u class=\"m-clave\">pena</u> que sustituya.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-32,18-169,18-195,18-236,18-ia-1144\">🎯 5 preguntas</mark></p><p><b>6.</b> <mark class=\"m-destacable\">Las penas accesorias</mark> <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-personalizado\">la <u class=\"m-clave\">duración</u></mark> que <span class=\"ex-plg\"><span class=\"ex-plg-t\">respectivamente <mark class=\"m-personalizado\">tenga la pena principal, excepto</mark> lo que dispongan expresamente <mark class=\"m-personalizado\">otros <u class=\"m-clave\">preceptos</u></mark> de este Código.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1145\">🎯 1 pregunta</mark></p><p><b>7.</b> Las penas aplicables a las <mark class=\"m-autoridad\">personas</mark> jurídicas, que tienen <mark class=\"m-personalizado\">todas la consideración de</mark> <mark class=\"m-resp\" data-q=\"18-164\">graves</mark>, <mark class=\"m-personalizado\">son las siguientes:</mark></p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-personalizado\">Disolución</mark> de la <mark class=\"m-autoridad\">persona</mark> jurídica. La disolución <mark class=\"m-accion\">producirá</mark> la <mark class=\"m-resp r-ia\" data-q=\"18-ia-1147\">pérdida definitiva de su personalidad jurídica, así como la de su capacidad de actuar de cualquier modo en el tráfico jurídico, o llevar a cabo cualquier clase de actividad, aunque sea lícita</mark>.</p><p style=\"margin-left:18px\" data-ex=\"*\"><b>c)</b> <mark class=\"m-personalizado\">Suspensión</mark> de sus actividades <mark class=\"m-personalizado\">por un plazo</mark> que <mark class=\"m-accion\">no podrá exceder</mark> de cinco años.</p><p style=\"margin-left:18px\" data-ex=\"*\"><b>d)</b> Clausura de sus locales y establecimientos por un plazo que <mark class=\"m-accion\">no podrá exceder</mark> de cinco años.</p><p style=\"margin-left:18px\"><b>e)</b> <mark class=\"m-personalizado\">Prohibición de realizar en</mark> el futuro las actividades <mark class=\"m-personalizado\">en cuyo ejercicio</mark> se haya cometido, favorecido <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u></mark> encubierto el delito. Esta prohibición <mark class=\"m-accion\">podrá</mark> ser temporal o <mark class=\"m-personalizado\"><u class=\"m-clave\">definitiva.</u></mark> Si fuere <mark class=\"m-personalizado\">temporal, el plazo</mark> <mark class=\"m-accion\">no podrá exceder</mark> <mark class=\"m-personalizado\">de <mark class=\"m-resp\" data-q=\"18-240,18-ia-1149\">quince años</mark>.</mark></p><p style=\"margin-left:18px\"><b><mark class=\"m-personalizado\">f)</mark></b> <mark class=\"m-personalizado\">Inhabilitación para obtener subvenciones y ayudas públicas, para contratar con el sector público y para gozar de beneficios e incentivos</mark> <mark class=\"m-autoridad\">fiscales</mark> <mark class=\"m-personalizado\">o de la Seguridad Social, por un plazo que</mark> <mark class=\"m-accion\">no podrá exceder</mark> <mark class=\"m-personalizado\">de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1150\">quince años</mark>.</mark></p><p style=\"margin-left:18px\" data-ex=\"*\"><b><mark class=\"m-personalizado\">g)</mark></b> <mark class=\"m-personalizado\">Intervención judicial</mark> para <mark class=\"m-personalizado\">salvaguardar</mark> los derechos de <mark class=\"m-personalizado\">los trabajadores o</mark> de los <mark class=\"m-personalizado\">acreedores</mark> por el tiempo que se estime necesario, que <mark class=\"m-accion\">no podrá exceder</mark> de cinco años. <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1128\">🎯 1 pregunta</mark></p><p>La intervención <mark class=\"m-accion\">podrá afectar</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1151\">a la totalidad de la organización <mark class=\"m-personalizado\">o limitarse</mark> a alguna de sus instalaciones, secciones o unidades de negocio</mark>. El <mark class=\"m-autoridad\">Juez o Tribunal,</mark> en la sentencia o, posteriormente, mediante auto, <mark class=\"m-accion\">determinará</mark> exactamente <mark class=\"m-personalizado\">el contenido</mark> de la intervención y <mark class=\"m-accion\">determinará</mark> <mark class=\"m-personalizado\">quién</mark> <mark class=\"m-accion\">se hará</mark> <mark class=\"m-personalizado\">cargo</mark> de la intervención y en qué <mark class=\"m-personalizado\">plazos</mark> <mark class=\"m-accion\">deberá realizar</mark> <mark class=\"m-personalizado\">informes</mark> de seguimiento para el <mark class=\"m-autoridad\">órgano</mark> judicial. La intervención <mark class=\"m-accion\">se podrá modificar</mark> <mark class=\"m-personalizado\">o suspender</mark> en todo momento previo informe del interventor y del <mark class=\"m-autoridad\">Ministerio Fiscal.</mark> El interventor <mark class=\"m-accion\">tendrá</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">derecho a acceder a todas las instalaciones y locales de</span></span> la empresa o <mark class=\"m-autoridad\">persona</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">jurídica y a recibir cuanta información estime necesaria para el ejercicio de</span></span> sus funciones. Reglamentariamente <mark class=\"m-accion\">se determinarán</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">los aspectos relacionados con el ejercicio de la función de interventor, como la retribución o la cualificación necesaria.</span></span> <mark class=\"m-resp ex-q\" data-q=\"18-101\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><mark class=\"m-personalizado\">La <u class=\"m-clave\">clausura temporal</u> de los locales</mark> o establecimientos, <mark class=\"m-personalizado\">la suspensión de las actividades</mark> sociales <mark class=\"m-personalizado\">y la intervención judicial</mark> <mark class=\"m-accion\">podrán ser acordadas</mark> también por el <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"18-53\">Juez Instructor</mark></mark> <mark class=\"m-personalizado\">como medida cautelar</mark> durante la instrucción de la causa. <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1152\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>PENAS GRAVES · MENOS GRAVES · LEVES (cuadro del temario · art. 33; con sello EXAMEN)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5><mark class=\"m-resp\">GRAVES</mark></h5><ul><li>a) <mark class=\"m-personalizado\">Prisión</mark> <u class=\"m-clave\">permanente</u> revisable (<u class=\"m-clave\">siempre</u> <mark class=\"m-personalizado\">grave</mark>)</li><li>b) <mark class=\"m-personalizado\">Prisión</mark> <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">cinco años</mark></li><li>c) <u class=\"m-clave\">Inhabilitación</u> absoluta (<u class=\"m-clave\">siempre</u> <mark class=\"m-personalizado\">grave</mark>)</li><li>d) Inhabilitaciones especiales <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">cinco años</mark></li><li>e) <mark class=\"m-personalizado\">Suspensión de empleo o cargo público</mark> <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">cinco años</mark></li><li>f) <u class=\"m-clave\">Privación</u> <mark class=\"m-personalizado\">del derecho a conducir</mark> <mark class=\"m-personalizado\">vehículos a motor y ciclomotores</mark>: <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">ocho años</mark></li><li>g) <u class=\"m-clave\">Privación</u> del <mark class=\"m-personalizado\">derecho</mark> a <mark class=\"m-personalizado\">la tenencia y porte de armas</mark>: <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">ocho años</mark></li><li>h) <u class=\"m-clave\">Privación</u> del <mark class=\"m-personalizado\">derecho a residir</mark> en determinados <mark class=\"m-personalizado\">lugares o acudir</mark> a ellos: <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">cinco años</mark></li><li>i) <mark class=\"m-personalizado\">Prohibición</mark> de <mark class=\"m-personalizado\">aproximarse a</mark> la <mark class=\"m-autoridad\">víctima</mark>: <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">cinco años</mark></li><li>j) <mark class=\"m-personalizado\">Prohibición</mark> de <mark class=\"m-personalizado\">comunicarse con</mark> la <mark class=\"m-autoridad\">víctima</mark>: <u class=\"m-clave\">superior a</u> <mark class=\"m-plazo\">cinco años</mark></li><li>k) <u class=\"m-clave\">Privación</u> de <mark class=\"m-personalizado\">la patria potestad</mark> (<u class=\"m-clave\">siempre</u> <mark class=\"m-personalizado\">grave</mark>)</li></ul></div><div class=\"vis-col\"><h5>MENOS GRAVES</h5><ul><li>a) <mark class=\"m-personalizado\">Prisión</mark> de <mark class=\"m-plazo\"><u class=\"m-clave\">tres meses</u> hasta cinco años</mark></li><li>b) Inhabilitaciones especiales <mark class=\"m-personalizado\">hasta</mark> <mark class=\"m-plazo\">cinco años</mark></li><li>c) <mark class=\"m-personalizado\">Suspensión de empleo o cargo público</mark> <mark class=\"m-personalizado\">hasta</mark> <mark class=\"m-plazo\">cinco años</mark></li><li>d) <mark class=\"m-personalizado\">Conducir</mark>: de <mark class=\"m-plazo\">un año y un día a ocho años</mark></li><li>e) <mark class=\"m-personalizado\">Tenencia y porte de armas</mark>: de <mark class=\"m-plazo\">un año y un día a ocho años</mark></li><li>f) <u class=\"m-clave\">Inhabilitación</u> especial para <mark class=\"m-personalizado\">profesión, oficio o comercio</mark> relacionado con los <u class=\"m-clave\">animales y para</u> la tenencia de <mark class=\"m-personalizado\">animales</mark>: de <mark class=\"m-plazo\">un año y un día <u class=\"m-clave\">a cinco</u> años</mark></li><li>g) <mark class=\"m-personalizado\">Residir</mark>: de <mark class=\"m-plazo\">seis meses <u class=\"m-clave\">a cinco</u> años</mark></li><li>h) <mark class=\"m-personalizado\">Aproximarse</mark>: de <mark class=\"m-plazo\">seis meses <u class=\"m-clave\">a cinco</u> años</mark></li><li>i) <mark class=\"m-personalizado\">Comunicarse</mark>: de <mark class=\"m-plazo\">seis meses <u class=\"m-clave\">a cinco</u> años</mark></li><li>j) <mark class=\"m-personalizado\">Multa</mark> de <mark class=\"m-plazo\">más de <u class=\"m-clave\">tres meses</u></mark></li><li>k) <mark class=\"m-personalizado\">Multa</mark> <mark class=\"m-personalizado\">proporcional</mark>, <mark class=\"m-personalizado\">cualquiera que fuese su cuantía</mark> (<mark class=\"m-personalizado\">salvo</mark> lo dispuesto para <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas</mark>)</li><li>l) <mark class=\"m-personalizado\">Trabajos en beneficio de la comunidad</mark>: de <mark class=\"m-plazo\">treinta y un días a un año</mark></li></ul></div><div class=\"vis-col\"><h5>LEVES</h5><ul><li>a) <mark class=\"m-personalizado\">Conducir</mark>: de <mark class=\"m-plazo\"><u class=\"m-clave\">tres meses a</u> un año</mark></li><li>b) <mark class=\"m-personalizado\">Tenencia y porte de armas</mark>: de <mark class=\"m-plazo\"><u class=\"m-clave\">tres meses a</u> un año</mark></li><li>c) <mark class=\"m-personalizado\">Animales</mark> (<u class=\"m-clave\">inhabilitación</u> especial): de <mark class=\"m-plazo\"><u class=\"m-clave\">tres meses a</u> un año</mark></li><li>d) <mark class=\"m-personalizado\">Residir</mark>: <mark class=\"m-plazo\"><u class=\"m-clave\">inferior</u> a seis meses</mark></li><li>e) <mark class=\"m-personalizado\">Aproximarse</mark>: de <mark class=\"m-plazo\">un mes a <u class=\"m-clave\">menos</u> de seis meses</mark></li><li>f) <mark class=\"m-personalizado\">Comunicarse</mark>: de <mark class=\"m-plazo\">un mes a <u class=\"m-clave\">menos</u> de seis meses</mark></li><li>g) <mark class=\"m-personalizado\">Multa</mark> de <mark class=\"m-plazo\">hasta <u class=\"m-clave\">tres meses</u></mark></li><li>h) <mark class=\"m-personalizado\">Trabajos en beneficio de la comunidad</mark>: de <mark class=\"m-plazo\"><u class=\"m-clave\">uno a</u> treinta días</mark></li><li>i) <mark class=\"m-personalizado\">Localización</mark> <u class=\"m-clave\">permanente</u>: de <mark class=\"m-plazo\">un día a <u class=\"m-clave\">tres meses</u></mark></li></ul></div></div></div><div class=\"trampa\"><b>⚠ Cifras que se confunden</b><p><strong><mark class=\"m-personalizado\">Multa</mark> de más de <mark class=\"m-personalizado\">tres</mark> meses</strong> = <u class=\"m-clave\">pena</u> <strong><u class=\"m-clave\">menos</u> <mark class=\"m-personalizado\">grave</mark></strong> · <strong><mark class=\"m-personalizado\">hasta</mark> <mark class=\"m-personalizado\">tres</mark> meses</strong> = <u class=\"m-clave\">pena</u> <strong><mark class=\"m-personalizado\">leve</mark></strong> · la <strong><mark class=\"m-personalizado\">multa</mark> <mark class=\"m-personalizado\">proporcional</mark></strong>, cualquiera que sea su cuantía, es <u class=\"m-clave\">menos</u> <mark class=\"m-personalizado\">grave</mark> (<mark class=\"m-personalizado\">salvo</mark> las de <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas</mark>, que son <mark class=\"m-destacable\">graves</mark>).</p>"],["Artículo 34 <span class=\"ex-sello\">EX</span>","<p><b>1.</b> <mark class=\"m-personalizado\">La detención y prisión preventiva</mark> y <mark class=\"m-personalizado\">las demás medidas cautelares de naturaleza</mark> penal. <mark class=\"m-resp ex-q\" data-q=\"18-182\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.</b> <mark class=\"m-personalizado\">Las multas y demás correcciones</mark> que, en uso de <mark class=\"m-personalizado\">atribuciones gubernativas o disciplinarias,</mark> se impongan a los subordinados o administrados.</p>"],["Artículo 36 <span class=\"ex-sello\">EXOF</span>","<p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-personalizado\">Hasta el cumplimiento de</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1156,18-ia-1203\">veinte años de prisión efectiva</mark>, en el <span class=\"ex-plg\"><span class=\"ex-plg-t\">caso de que el penado lo <mark class=\"m-personalizado\">hubiera sido por un delito del Capítulo</mark> VII del Título XXII del Libro II de este Código.</span></span></p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-personalizado\">Hasta el cumplimiento</mark> <mark class=\"m-plazo\">de</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1155\">quince</mark> años de prisión efectiva, <mark class=\"m-personalizado\"><u class=\"m-clave\">en el</u> resto de los casos.</mark></p><p>En estos supuestos, el penado <mark class=\"m-accion\">no podrá disfrutar</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">permisos de salida</mark> <mark class=\"m-personalizado\">hasta</mark> que haya cumplido un mínimo de doce años de prisión, en el caso previsto en la letra a), y <mark class=\"m-resp r-ia\" data-q=\"18-ia-1204\">ocho años de prisión</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">en el previsto en la letra b).</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1157\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF\"><b>2.</b> <mark class=\"m-destacable\">La pena de prisión</mark> <mark class=\"m-accion\">tendrá</mark> una <mark class=\"m-personalizado\">duración</mark> mínima de tres meses y máxima de veinte años, <mark class=\"m-personalizado\">salvo</mark> lo <mark class=\"m-personalizado\">que excepcionalmente dispongan</mark> otros preceptos del presente <mark class=\"m-personalizado\">Código.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-262,18-ia-1158,18-ia-1201\">🎯 3 preguntas</mark></p><p>Cuando la duración de la pena de <mark class=\"m-personalizado\">prisión</mark> impuesta sea superior a cinco años, el <mark class=\"m-autoridad\">juez o tribunal</mark> <mark class=\"m-accion\">podrá ordenar</mark> que la clasificación del condenado en el <mark class=\"m-destacable\">tercer grado</mark> de tratamiento penitenciario no <mark class=\"m-personalizado\">se efectúe hasta el cumplimiento de la mitad de la pena</mark> impuesta.  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1159,18-ia-1202\">🎯 2 preguntas</mark></p><p><b><mark class=\"m-autoridad\">3.</mark></b> <mark class=\"m-autoridad\">La autoridad judicial de vigilancia</mark> penitenciaria, <mark class=\"m-personalizado\">previo pronóstico individualizado y favorable</mark> de <mark class=\"m-personalizado\">reinserción social y valorando,</mark> <mark class=\"m-autoridad\">en su caso, las</mark> <mark class=\"m-personalizado\">circunstancias personales de la</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">condenada y la evolución</mark> del tratamiento reeducador, <mark class=\"m-accion\">podrá acordar</mark> <mark class=\"m-personalizado\">razonadamente, oídos</mark> <mark class=\"m-autoridad\">el Ministerio Fiscal, Instituciones Penitenciarias y las demás</mark> <mark class=\"m-personalizado\">partes, la aplicación del</mark> <mark class=\"m-destacable\">régimen general de cumplimiento,</mark> salvo <mark class=\"m-personalizado\">en</mark> los supuestos contenidos en el <mark class=\"m-personalizado\">apartado anterior.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-208,18-ia-1161\">🎯 2 preguntas</mark></p><p><b>4.</b> En todo caso, la <mark class=\"m-autoridad\">autoridad judicial de vigilancia penitenciaria,</mark> según corresponda, <mark class=\"m-accion\">podrá acordar,</mark> previo informe del <mark class=\"m-autoridad\">Ministerio Fiscal, Instituciones Penitenciarias y las demás</mark> partes, <mark class=\"m-personalizado\">la progresión a <u class=\"m-clave\">tercer</u> grado por</mark> <mark class=\"m-destacable\">motivos humanitarios y de dignidad <u class=\"m-clave\">personal</u></mark> de las <mark class=\"m-autoridad\">personas</mark> condenadas <mark class=\"m-personalizado\">enfermas muy graves</mark> con padecimientos <mark class=\"m-personalizado\"><u class=\"m-clave\">incurables</u></mark> y de las <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1206\">septuagenarias</mark>,</u> valorando,</mark> especialmente, <mark class=\"m-personalizado\">su</mark> escasa peligrosidad. <mark class=\"m-resp ex-q\" data-q=\"18-220,18-239,18-ia-1162\">🎯 3 preguntas</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>PERMISOS DE SALIDA · prisión permanente revisable (cuadro del temario · art. 36.1)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">12 <mark class=\"m-plazo\">años</mark></span><u class=\"m-clave\">No</u> <mark class=\"m-accion\">podrá</mark> disfrutar de <mark class=\"m-destacable\">permisos de salida</mark> <mark class=\"m-personalizado\">hasta</mark> <u class=\"m-clave\">el cumplimiento</u> de <mark class=\"m-plazo\">12 años</mark> <mark class=\"m-personalizado\">de prisión</mark> efectiva, <mark class=\"m-personalizado\">en el caso de</mark> que el penado lo sea por <mark class=\"m-personalizado\">un delito</mark> del Capítulo VII del <u class=\"m-clave\">Título</u> XXII del Libro II del <mark class=\"m-personalizado\">Código</mark> <u class=\"m-clave\">Penal</u> (<mark class=\"m-destacable\">terrorismo</mark>). <u class=\"m-clave\">Tercer</u> <mark class=\"m-personalizado\">grado</mark>: <mark class=\"m-plazo\">20 años</mark>.</div><div class=\"vis-plazo\"><span class=\"n\">8 <mark class=\"m-plazo\">años</mark></span><u class=\"m-clave\">No</u> <mark class=\"m-accion\">podrá</mark> disfrutar de <mark class=\"m-destacable\">permisos de salida</mark> <mark class=\"m-personalizado\">hasta</mark> <u class=\"m-clave\">el cumplimiento</u> de <mark class=\"m-plazo\">8 años</mark> <mark class=\"m-personalizado\">de prisión</mark> efectiva, <mark class=\"m-personalizado\">en el resto de los casos</mark>. <u class=\"m-clave\">Tercer</u> <mark class=\"m-personalizado\">grado</mark>: <mark class=\"m-plazo\">15 años</mark>.</div></div></div><div class=\"trampa\"><b>⚠ Ojo a la redacción</b><p><mark class=\"m-personalizado\">Prisión</mark> de más de <mark class=\"m-personalizado\">cinco años</mark>: <mark class=\"m-autoridad\">el juez</mark> <strong>«<mark class=\"m-accion\">podrá</mark>» ordenar</strong> que el <u class=\"m-clave\">tercer</u> <mark class=\"m-personalizado\">grado</mark> <u class=\"m-clave\">no</u> se conceda <mark class=\"m-personalizado\">hasta</mark> cumplir <strong>la <mark class=\"m-personalizado\">mitad</mark> de la <u class=\"m-clave\">pena</u></strong>; pero en <mark class=\"m-personalizado\">los delitos</mark> enumerados (<mark class=\"m-destacable\">terrorismo</mark>, organización o grupo <u class=\"m-clave\">criminal</u>, art. 183, Capítulo V del <u class=\"m-clave\">Título</u> VIII…) <strong>«<mark class=\"m-personalizado\">en cualquier caso</mark>»</strong>, <u class=\"m-clave\">sin</u> potestad del <mark class=\"m-autoridad\">juez</mark>.</p></div><div class=\"trampa\"><b>⚠ Cifras que se confunden</b><p><em><mark class=\"m-destacable\">Permisos de salida</mark> en la <mark class=\"m-personalizado\">prisión</mark> <u class=\"m-clave\">permanente</u> revisable (art. 36.1)</em><strong>12 <mark class=\"m-plazo\">años</mark> (<u class=\"m-clave\">tercer</u> <mark class=\"m-personalizado\">grado</mark> a los 20, <mark class=\"m-destacable\">terrorismo</mark>) · 8 <mark class=\"m-plazo\">años</mark> (<u class=\"m-clave\">tercer</u> <mark class=\"m-personalizado\">grado</mark> a los 15, <mark class=\"m-personalizado\">resto</mark> de <mark class=\"m-personalizado\">casos</mark>)</strong> — <u class=\"m-clave\">no</u> 8 <mark class=\"m-plazo\">años</mark> en <mark class=\"m-destacable\">terrorismo</mark> · <u class=\"m-clave\">no</u> 12 <mark class=\"m-plazo\">años</mark> <mark class=\"m-personalizado\">en el resto</mark> · <u class=\"m-clave\">no</u> 15 y 20 <mark class=\"m-plazo\">años</mark> para los permisos</p>"],["Artículo 38","<p><b>1.</b> Cuando el <mark class=\"m-personalizado\">reo estuviere <u class=\"m-clave\">preso,</u></mark> la duración de las <mark class=\"m-personalizado\">penas</mark> <mark class=\"m-accion\">empezará</mark> <mark class=\"m-personalizado\">a computarse</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1210\">desde el día en que la sentencia condenatoria haya quedado firme</mark>.</p><p><b>2.</b> Cuando el <mark class=\"m-personalizado\">reo no estuviere preso,</mark> la duración <span class=\"ex-plg\"><span class=\"ex-plg-t\">de las <mark class=\"m-personalizado\">penas</mark> <mark class=\"m-accion\">empezará</mark> <mark class=\"m-personalizado\">a contarse</mark> <mark class=\"m-plazo\">desde que ingrese en el establecimiento</mark> adecuado para su cumplimiento.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-241,18-ia-1209\">🎯 2 preguntas</mark></p>"],["Artículo 49","<p><mark class=\"m-personalizado\">Los trabajos en beneficio de la comunidad,</mark> que <mark class=\"m-accion\">no podrán imponerse</mark> <mark class=\"m-personalizado\">sin el consentimiento de la</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">condenada,</mark> le obligan a prestar su cooperación <mark class=\"m-personalizado\">no retribuida</mark> en determinadas actividades <mark class=\"m-personalizado\">de utilidad pública,</mark> que <mark class=\"m-accion\">podrán consistir,</mark> en relación con delitos de similar naturaleza al cometido por la <mark class=\"m-autoridad\">persona</mark> condenada, en labores de reparación de los daños causados <mark class=\"m-personalizado\">o</mark> de apoyo o asistencia a las víctimas, así como en la participación de la <mark class=\"m-autoridad\">persona</mark> condenada en talleres o programas formativos de reeducación, laborales, culturales, de educación vial, sexual, resolución pacífica de conflictos, parentalidad positiva y otros similares. <mark class=\"m-plazo\">Su duración diaria</mark> <mark class=\"m-accion\">no podrá exceder</mark> <mark class=\"m-plazo\">de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1229\">ocho horas</mark> y sus</mark> <mark class=\"m-personalizado\">condiciones</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">las siguientes:</mark></p><p style=\"margin-left:18px\"><b><mark class=\"m-personalizado\">a)</mark></b> <mark class=\"m-personalizado\">Se ausenta</mark> del <mark class=\"m-plazo\">trabajo</mark> durante al menos <mark class=\"m-resp r-ia\" data-q=\"18-ia-1231\">dos jornadas laborales, <mark class=\"m-personalizado\">siempre que ello suponga un rechazo voluntario</mark> por su parte al cumplimiento de la pena</mark>.</p><p style=\"margin-left:18px\"><b><mark class=\"m-personalizado\">b)</mark></b> <mark class=\"m-personalizado\">A pesar de los requerimientos</mark> del responsable del centro <span class=\"ex-plg\"><span class=\"ex-plg-t\">de trabajo, su <mark class=\"m-personalizado\">rendimiento fuera sensiblemente inferior al mínimo exigible.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-228\">🎯 1 pregunta</mark></p><p><b>7.ª</b> Si el penado <mark class=\"m-personalizado\">faltara del trabajo por causa justificada</mark> <mark class=\"m-accion\">no se entenderá</mark> como <mark class=\"m-personalizado\">abandono</mark> de la actividad. <mark class=\"m-personalizado\">No obstante, el</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1232\">trabajo <mark class=\"m-personalizado\">perdido no se le</mark> <mark class=\"m-accion\">computará</mark> <mark class=\"m-personalizado\">en la liquidación</mark> de la condena</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">en la que <mark class=\"m-accion\">se deberán hacer</mark> constar los días o jornadas que efectivamente hubiese trabajado del total que se le hubiera impuesto.</span></span></p>"],["Artículo 50 <span class=\"ex-sello ex-sello-r\">R19</span> <span class=\"ex-sello ex-sello-r\">R20</span>","<p data-ex=\"EXAMEN\"><b>1.</b> La pena de <mark class=\"m-destacable\">multa</mark> <mark class=\"m-accion\">consistirá</mark> en la imposición al condenado de una <mark class=\"m-personalizado\">sanción pecuniaria.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-263\">🎯 1 pregunta</mark></p><p><b>2.</b> La pena de multa <mark class=\"m-accion\">se impondrá,</mark> <mark class=\"m-personalizado\">salvo</mark> que <mark class=\"m-personalizado\">la Ley</mark> disponga <mark class=\"m-personalizado\">otra cosa,</mark> por el <mark class=\"m-destacable\">sistema de días-multa.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-55\">🎯 1 pregunta</mark></p><p data-r=\"R20\"><span class=\"ex-sello ex-sello-r\">R20</span> <b>4.</b> <mark class=\"m-destacable\">La cuota diaria</mark> <mark class=\"m-accion\">tendrá</mark> un <mark class=\"m-personalizado\">mínimo de dos y un máximo de 400 euros, excepto</mark> en el caso <mark class=\"m-personalizado\">de las</mark> multas imponibles a <mark class=\"m-personalizado\">las</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">jurídicas,</mark> en las que la cuota diaria <mark class=\"m-accion\">tendrá</mark> un <mark class=\"m-personalizado\">mínimo de 30 y un máximo de 5.000 euros. A efectos de cómputo,</mark> cuando se fije la duración por <mark class=\"m-personalizado\">meses o por años,</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-destacable\">que</mark> los <mark class=\"m-resp r-ia\" data-q=\"18-ia-1236\">meses son de treinta días y los años de trescientos sesenta</mark>. <mark class=\"m-resp ex-q\" data-q=\"18-222\">🎯 1 pregunta</mark></p><p><b>5.</b> Los <mark class=\"m-autoridad\">Jueces o Tribunales</mark> <mark class=\"m-accion\">determinarán</mark> motivadamente la extensión de la pena dentro de los límites establecidos para cada delito y según las reglas del capítulo II de este <mark class=\"m-personalizado\"><u class=\"m-clave\">Título.</u> Igualmente,</mark> <mark class=\"m-accion\">fijarán</mark> en la sentencia, el importe de estas cuotas, teniendo en cuenta para <mark class=\"m-personalizado\">ello exclusivamente la situación económica del reo,</mark> deducida de su <mark class=\"m-personalizado\">patrimonio, ingresos, obligaciones y cargas familiares y demás</mark> circunstancias personales del mismo.  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1237\">🎯 1 pregunta</mark></p><p><b>6.</b> <mark class=\"m-autoridad\">El tribunal,</mark> <mark class=\"m-personalizado\">por causa justificada,</mark> <mark class=\"m-accion\">podrá autorizar</mark> <mark class=\"m-personalizado\">el pago</mark> de la multa <mark class=\"m-plazo\">dentro de un plazo que no</mark> <mark class=\"m-autoridad\">exceda de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1238\">dos años</mark> desde</mark> <mark class=\"m-plazo\">la</mark> <mark class=\"m-autoridad\">firmeza</mark> de la sentencia, bien <mark class=\"m-personalizado\">de una vez o en los plazos</mark> que se determinen.  <span class=\"ex-plg\"><span class=\"ex-plg-t\">En este caso, <mark class=\"m-destacable\">el impago de dos</mark> de ellos <mark class=\"m-accion\">determinará</mark> <mark class=\"m-personalizado\">el vencimiento de los restantes.</mark></span></span></p></div></div><div class=\"trampa\"><b>⚠ Cifras que se confunden</b><p><em>Cuota diaria de <mark class=\"m-personalizado\">la multa</mark> (art. 50.4)</em><strong>2 a 400 euros · <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas</mark> 30 a 5.000 euros</strong> — <u class=\"m-clave\">no</u> 3 a 500 euros · <u class=\"m-clave\">no</u> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas</mark> 30 a 2.000 euros · <u class=\"m-clave\">no</u> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas</mark> 2 a 5.000 euros</p></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 51: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1239\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 52: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1240,18-ia-1241\">🎯 2 preguntas más de este artículo</mark>"],["<mark class=\"m-personalizado\">Artículo 55</mark> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-personalizado\">La pena de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">prisión igual o superior</u></mark> a diez años <mark class=\"m-accion\">llevará</mark> consigo la <mark class=\"m-resp r-ia\" data-q=\"18-ia-1250\">inhabilitación absoluta durante el tiempo de la condena</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">salvo que ésta ya estuviere <mark class=\"m-personalizado\">prevista como pena principal para el</mark> supuesto de que <mark class=\"m-personalizado\">se</mark> trate.</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Juez</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">además disponer la inhabilitación especial para</mark> el <mark class=\"m-personalizado\">ejercicio</mark> de <mark class=\"m-personalizado\">la patria potestad, tutela,</mark> curatela, guarda o acogimiento, <mark class=\"m-personalizado\">o bien la privación</mark> de <mark class=\"m-personalizado\">la patria potestad, cuando estos</mark> derechos hubieren <mark class=\"m-personalizado\">tenido relación directa con el delito</mark> cometido.</span></span> Esta vinculación <mark class=\"m-accion\">deberá determinarse</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1249\">expresamente en la sentencia</mark>.</p>"],["Artículo 66 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span>","<p><b>1.ª</b> Cuando concurra <mark class=\"m-destacable\">sólo</mark> <span class=\"m-caja\"><mark class=\"m-destacable\">una</mark></span> circunstancia <mark class=\"m-destacable\">atenuante,</mark> <mark class=\"m-accion\">aplicarán</mark> la pena <mark class=\"m-resp r-ia\" data-q=\"18-ia-1268\">en la mitad inferior de la que fije la ley para el delito</mark>.</p><p><b>2.ª</b> Cuando concurran <mark class=\"m-destacable\">dos o</mark> <mark class=\"m-personalizado\">más</mark> <mark class=\"m-destacable\">circunstancias atenuantes,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o <mark class=\"m-destacable\">una <u class=\"m-clave\">o</u> varias muy cualificadas,</mark> y no</span></span> concurra agravante alguna, <mark class=\"m-accion\">aplicarán</mark> la <mark class=\"m-resp r-ia\" data-q=\"18-ia-1269\">pena inferior en uno o dos grados a la establecida por la ley, atendidos el número y la entidad de dichas circunstancias atenuantes</mark>.</p><p data-ex=\"*\"><b><mark class=\"m-personalizado\">3.ª</mark></b> <mark class=\"m-personalizado\">Cuando concurra sólo una o dos circunstancias agravantes,</mark> <mark class=\"m-accion\">aplicarán</mark> la pena <mark class=\"m-resp\" data-q=\"18-267,18-ia-1270\">en la mitad superior de la que fije <mark class=\"m-destacable\">la ley para</mark> el delito</mark>.</p><p data-ex=\"*,EXOF\"><b>4.ª</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando concurran más de dos circunstancias agravantes</span></span> y no concurra <mark class=\"m-destacable\">atenuante</mark> alguna, <mark class=\"m-accion\">podrán aplicar</mark> la <mark class=\"m-resp r-ia\" data-q=\"18-ia-1271\">pena superior en grado a la establecida por la ley, en su <mark class=\"m-personalizado\">mitad</mark> inferior</mark>. <mark class=\"m-resp ex-q\" data-q=\"18-52,18-93\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>5.ª</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Cuando concurra la circunstancia agravante de reincidencia con</span></span> la cualificación de <mark class=\"m-personalizado\">que el culpable al delinquir hubiera sido condenado</mark> ejecutoriamente, al menos, por tres delitos <mark class=\"m-personalizado\">comprendidos en el mismo título de este Código, siempre que sean de</mark> la misma naturaleza, <mark class=\"m-accion\">podrán aplicar</mark> la <mark class=\"m-resp\" data-q=\"18-268\">pena superior en grado a la prevista por la ley para el delito de que se trate, teniendo en cuenta las condenas precedentes, <mark class=\"m-personalizado\">así como la gravedad del</mark> nuevo delito cometido</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1272\">🎯 1 pregunta</mark></p><p>A los efectos de esta <span class=\"ex-plg\"><span class=\"ex-plg-t\">regla <mark class=\"m-accion\">no se computarán</mark> los antecedentes penales <mark class=\"m-personalizado\">cancelados o</mark> que <mark class=\"m-personalizado\">debieran serlo.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1273\">🎯 1 pregunta</mark></p><p><b>6.ª</b> Cuando <mark class=\"m-destacable\">no concurran atenuantes <u class=\"m-clave\">ni</u> agravantes</mark> <mark class=\"m-accion\">aplicarán</mark> <mark class=\"m-personalizado\">la</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">pena establecida por la ley para el delito cometido, en <mark class=\"m-personalizado\">la extensión que estimen adecuada, en atención a las circunstancias personales del delincuente</mark> y a <mark class=\"m-personalizado\">la mayor o</mark> <mark class=\"m-autoridad\">menor</mark> <mark class=\"m-personalizado\">gravedad del hecho.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1274\">🎯 1 pregunta</mark></p><p><b>7.ª</b> Cuando <mark class=\"m-personalizado\">concurran atenuantes y agravantes,</mark> <mark class=\"m-destacable\">las</mark> <mark class=\"m-accion\">valorarán</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">y</mark> <mark class=\"m-accion\">compensarán</mark> <mark class=\"m-personalizado\">racionalmente</mark> para la individualización de la pena. En el caso de <mark class=\"m-personalizado\">persistir un fundamento</mark> cualificado <mark class=\"m-personalizado\">de</mark> <mark class=\"m-autoridad\">atenuación</mark> <mark class=\"m-accion\">aplicarán</mark> la pena <mark class=\"m-autoridad\">inferior en grado.</mark> Si se mantiene un fundamento cualificado de <mark class=\"m-personalizado\">agravación,</mark> <mark class=\"m-accion\">aplicarán</mark> la pena en su <mark class=\"m-autoridad\">mitad superior.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1275\">🎯 1 pregunta</mark></p><p><b>8.ª</b> <mark class=\"m-personalizado\">Cuando</mark> los <mark class=\"m-autoridad\">jueces o tribunales</mark> <mark class=\"m-personalizado\">apliquen</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">la pena <mark class=\"m-destacable\">inferior en más de un</mark> <mark class=\"m-personalizado\">grado</mark> <mark class=\"m-accion\">podrán hacerlo</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">en toda</u> su extensión.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1276\">🎯 1 pregunta</mark></p><p><b>2.</b> En los <mark class=\"m-destacable\">delitos leves</mark> <mark class=\"m-personalizado\">y</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en los delitos <mark class=\"m-personalizado\">imprudentes,</mark> los <mark class=\"m-autoridad\">jueces o tribunales</mark> <mark class=\"m-accion\">aplicarán</mark> <mark class=\"m-personalizado\">las reglas a su</mark> <mark class=\"m-autoridad\">prudente arbitrio,</mark> sin sujetarse a las reglas prescritas en el apartado anterior, salvo lo dispuesto para los tipos agravados por multirreincidencia de delitos leves.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1277\">🎯 1 pregunta</mark></p></div></div><div class=\"trampa\"><b>⚠ Ojo a la redacción</b><p><strong>Una o <mark class=\"m-personalizado\">dos</mark> <mark class=\"m-destacable\">agravantes</mark></strong> → «<mark class=\"m-accion\">aplicarán</mark>» la <u class=\"m-clave\">pena</u> en la <mark class=\"m-personalizado\">mitad</mark> <u class=\"m-clave\">superior</u> (obligatorio). <strong>Más de <mark class=\"m-personalizado\">dos</mark> <mark class=\"m-destacable\">agravantes</mark></strong> y ninguna <mark class=\"m-destacable\">atenuante</mark>, o <strong>reincidencia cualificada</strong> → «<mark class=\"m-accion\">podrán aplicar</mark>» la <u class=\"m-clave\">pena superior</u> <mark class=\"m-destacable\">en grado</mark> (potestativo).</p></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 66 bis: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1278,18-ia-1279,18-ia-1280,18-ia-1301,18-ia-1302\">🎯 5 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 67: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1303\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 68: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1304\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 70 <span class=\"ex-sello\">✱</span>","<p><b>1.ª</b> <mark class=\"m-personalizado\">La pena superior en grado</mark> <mark class=\"m-accion\">se formará</mark> partiendo de la cifra máxima señalada por la ley para el delito de que se trate y <mark class=\"m-personalizado\">aumentando <u class=\"m-clave\">a ésta</u> la</mark> mitad de su cuantía, constituyendo la suma resultante <mark class=\"m-personalizado\">su</mark> límite <mark class=\"m-personalizado\">máximo.</mark> El <mark class=\"m-resp\" data-q=\"18-78,18-ia-1307\">límite mínimo de la pena superior en grado <mark class=\"m-accion\">será</mark> el máximo de la pena señalada por la ley para el delito de que se trate, <mark class=\"m-personalizado\">incrementado en un <u class=\"m-clave\">día o</u> en un día multa</mark> según la naturaleza de la pena a imponer</mark>. <mark class=\"m-resp ex-q\" data-q=\"18-83,18-ia-1306\">🎯 2 preguntas</mark></p><p><b>2.ª</b> <mark class=\"m-personalizado\">La pena <u class=\"m-clave\">inferior</u> en grado</mark> <mark class=\"m-accion\">se formará</mark> <mark class=\"m-resp\" data-q=\"18-82\">partiendo de <mark class=\"m-personalizado\">la cifra mínima</mark> señalada para el delito de que se trate <mark class=\"m-personalizado\">y deduciendo</mark> de ésta <mark class=\"m-personalizado\">la mitad de su cuantía, constituyendo</mark> el resultado de tal deducción <mark class=\"m-personalizado\">su límite mínimo. El límite máximo</mark> de la pena inferior en grado <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">el</u> mínimo de la pena</mark> señalada por la ley para el delito de que se trate, <mark class=\"m-personalizado\">reducido en un día o en un día multa</mark> según la naturaleza de la pena a imponer</mark>.</p><p><b>2.</b> <mark class=\"m-personalizado\">A los efectos de determinar la mitad superior o inferior</mark> de la pena o de concretar la pena inferior o superior en grado, <mark class=\"m-personalizado\"><u class=\"m-clave\">el día</u> o el día multa</mark> <mark class=\"m-accion\">se considerarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">indivisibles</u></mark> y actuaran como unidades penológicas de más o menos, según los casos.  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1308\">🎯 1 pregunta</mark></p><p><b>1.º</b> Si la pena determinada fuera la <mark class=\"m-personalizado\">de prisión,</mark> la misma pena, con la cláusula de que <mark class=\"m-plazo\">su duración máxima</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-plazo\">de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1309\">30 años</mark>.</mark></p><p><b>3.º</b> Si fuera de <mark class=\"m-personalizado\">suspensión de empleo o cargo público,</mark> la misma pena, con la cláusula de que <mark class=\"m-plazo\">su duración máxima</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-plazo\">de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1310\">ocho años</mark>.</mark></p><p data-ex=\"*\"><b>4.º</b> Tratándose de privación del <mark class=\"m-personalizado\">derecho a conducir</mark> vehículos a motor y ciclomotores, la misma pena, con la cláusula de que <mark class=\"m-plazo\">su duración máxima</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-plazo\">de <mark class=\"m-resp\" data-q=\"18-270,18-ia-1311\">15 años</mark>.</mark></p><p data-ex=\"*\"><b>5.º</b> Tratándose de privación del derecho a la <mark class=\"m-personalizado\">tenencia y porte de armas,</mark> la misma pena, con la cláusula de que <mark class=\"m-plazo\">su duración máxima</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-plazo\">de <mark class=\"m-resp\" data-q=\"18-271,18-ia-1312\">20 años</mark>.</mark></p><p><b>9.º</b> Si fuera de <mark class=\"m-personalizado\">multa,</mark> la misma pena, con la cláusula de que <mark class=\"m-plazo\">su duración máxima</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-plazo\">de <mark class=\"m-resp r-ia\" data-q=\"18-ia-1313\">30 meses</mark>.</mark></p><p><b>4.</b> <mark class=\"m-personalizado\">La pena inferior en grado</mark> a la de <mark class=\"m-plazo\">prisión permanente</mark> es la pena de <mark class=\"m-plazo\">prisión de veinte a treinta años.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1314\">🎯 1 pregunta</mark></p>"],["Artículo 74 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> <mark class=\"m-personalizado\">No obstante</mark> lo dispuesto en el <span class=\"ex-plg\"><span class=\"ex-plg-t\">artículo anterior, el que, en ejecución de un <mark class=\"m-personalizado\">plan preconcebido</mark> o <mark class=\"m-personalizado\">aprovechando idéntica ocasión,</mark> realice una <mark class=\"m-personalizado\">pluralidad de acciones u omisiones</mark> <u class=\"m-clave\">que</u> <mark class=\"m-personalizado\">ofendan</mark> a <mark class=\"m-personalizado\">uno o varios sujetos</mark> e infrinjan el mismo <mark class=\"m-personalizado\">precepto penal o preceptos</mark> de igual o semejante <mark class=\"m-personalizado\">naturaleza,</mark> <mark class=\"m-accion\">será castigado</mark> <mark class=\"m-autoridad\">como autor</mark> de un <mark class=\"m-destacable\">delito o falta continuados</mark> con la <mark class=\"m-personalizado\">pena</mark> señalada para <mark class=\"m-destacable\">la infracción más grave, que</mark> <mark class=\"m-accion\">se impondrá</mark> <mark class=\"m-destacable\">en su mitad superior,</mark> <mark class=\"m-accion\">pudiendo llegar</mark> <mark class=\"m-autoridad\">hasta la mitad</mark> inferior de la pena superior en grado.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-193,18-ia-1319\">🎯 2 preguntas</mark></p><p><b>2.</b> Si <mark class=\"m-destacable\">se tratare de infracciones contra el patrimonio,</mark> <mark class=\"m-accion\">se impondrá</mark> <mark class=\"m-destacable\">la pena teniendo</mark> en <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">cuenta</mark> el perjuicio total causado. En estas infracciones <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">Juez o Tribunal</mark> <mark class=\"m-accion\">impondrá,</mark> <mark class=\"m-autoridad\">motivadamente, la pena superior en uno o dos grados,</mark> en la <mark class=\"m-personalizado\">extensión que estime conveniente,</mark> si el hecho revistiere <mark class=\"m-personalizado\"><u class=\"m-clave\">notoria</u> gravedad y hubiere perjudicado a una generalidad de</mark> <mark class=\"m-autoridad\">personas.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-41,18-ia-1320\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>3.</b> <mark class=\"m-personalizado\">Quedan</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">exceptuadas</u></mark> de lo establecido <span class=\"ex-plg\"><span class=\"ex-plg-t\">en los <mark class=\"m-personalizado\">apartados anteriores las ofensas a</mark> <mark class=\"m-destacable\">bienes <u class=\"m-clave\">eminentemente</u></mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">personales,</mark></span> <mark class=\"m-personalizado\">salvo</mark> las constitutivas de infracciones contra <mark class=\"m-personalizado\">el honor</mark> <mark class=\"m-autoridad\">y la libertad e indemnidad</mark> <mark class=\"m-personalizado\">sexuales</mark> que <mark class=\"m-personalizado\">afecten</mark> al <span class=\"m-caja\"><mark class=\"m-autoridad\">mismo sujeto</mark></span> <mark class=\"m-personalizado\">pasivo.</mark> En estos casos, <mark class=\"m-accion\">se atenderá</mark> a la <mark class=\"m-personalizado\">naturaleza</mark> del hecho <mark class=\"m-personalizado\">y del precepto infringido</mark> para aplicar o <mark class=\"m-personalizado\">no la continuidad</mark> delictiva.</span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-274,18-ia-1321\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 75: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1322\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 76 <span class=\"ex-sello\">EX</span>","<p><b>1.</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">No obstante</u></mark> lo dispuesto en el artículo anterior, <mark class=\"m-destacable\">el máximo</mark> de cumplimiento efectivo de la condena del culpable <mark class=\"m-accion\">no podrá exceder</mark> <mark class=\"m-destacable\">del triple del tiempo por el que se le imponga la más grave de las penas en que haya incurrido,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">declarando extinguidas las que procedan desde que las ya impuestas cubran</span></span> dicho máximo, que <mark class=\"m-accion\">no podrá exceder</mark> de <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1323\">20 años</mark>. Excepcionalmente, este</mark> <mark class=\"m-plazo\">límite máximo</mark> <mark class=\"m-accion\">será:</mark> <mark class=\"m-resp ex-q\" data-q=\"18-86\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b><mark class=\"m-plazo\">a)</mark></b> <mark class=\"m-plazo\">De</mark> 25 <mark class=\"m-plazo\">años,</mark> cuando el sujeto haya sido <mark class=\"m-personalizado\">condenado por dos o más delitos y alguno</mark> de ellos esté <mark class=\"m-personalizado\">castigado</mark> por <mark class=\"m-personalizado\">la ley</mark> con pena de prisión <mark class=\"m-personalizado\">de hasta 20 años.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1324\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b><mark class=\"m-plazo\">b)</mark></b> De 30 años, cuando el sujeto haya sido condenado por dos <mark class=\"m-personalizado\"><u class=\"m-clave\">o más</u> delitos y alguno de</mark> ellos esté castigado por la ley con pena de prisión <mark class=\"m-personalizado\">superior <u class=\"m-clave\">a 20 años.</u></mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1325\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\" data-ex=\"EX\"><b><mark class=\"m-plazo\">c)</mark></b> <mark class=\"m-plazo\">De <mark class=\"m-resp\" data-q=\"18-275\">40 años</mark>,</mark> cuando el sujeto haya sido condenado por <mark class=\"m-personalizado\"><u class=\"m-clave\">dos o</u> más</mark> delitos y, <mark class=\"m-personalizado\">al menos, dos</mark> de ellos estén castigados por la ley con pena de prisión <mark class=\"m-personalizado\"><u class=\"m-clave\">superior a</u> 20 años.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1326\">🎯 1 pregunta</mark></p><p><b>2.</b> La <mark class=\"m-personalizado\">limitación</mark> <mark class=\"m-accion\">se aplicará</mark> <mark class=\"m-personalizado\">aunque</mark> las <span class=\"ex-plg\"><span class=\"ex-plg-t\">penas se hayan impuesto en</span></span> <mark class=\"m-personalizado\">distintos procesos</mark> cuando lo hayan sido <mark class=\"m-resp r-ia\" data-q=\"18-ia-1327\">por hechos cometidos antes de la fecha en que fueron enjuiciados los que, siendo objeto de acumulación, lo hubieran sido en primer lugar</mark>.</p></div></div><div class=\"trampa\"><b>⚠ Cifras que se confunden</b><p><em><mark class=\"m-plazo\">Límite máximo</mark> de <mark class=\"m-personalizado\">cumplimiento</mark> (art. 76)</em><strong>Regla general: triple de la <u class=\"m-clave\">pena</u> más <mark class=\"m-personalizado\">grave</mark>, <mark class=\"m-personalizado\">máximo</mark> 20 <mark class=\"m-plazo\">años</mark> · 25 (alguno <mark class=\"m-personalizado\">hasta</mark> 20 <mark class=\"m-plazo\">años</mark>) · 30 (alguno <u class=\"m-clave\">superior a</u> 20) · 40 (<mark class=\"m-personalizado\">dos</mark> superiores a 20, o <mark class=\"m-destacable\">terrorismo</mark>)</strong> — <u class=\"m-clave\">no</u> triple <u class=\"m-clave\">sin</u> <mark class=\"m-personalizado\">máximo</mark> · <u class=\"m-clave\">no</u> 25 <mark class=\"m-personalizado\">si</mark> alguno es <u class=\"m-clave\">superior a</u> 20 · <u class=\"m-clave\">no</u> 30 con <mark class=\"m-personalizado\">dos</mark> superiores a 20</p></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 77: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1328,18-ia-1329,18-ia-1330\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 78 <span class=\"ex-sello\">EX</span>","<p><b><mark class=\"m-plazo\">1.</mark></b> <mark class=\"m-plazo\">Si a consecuencia de las limitaciones establecidas en el apartado</mark> 1 <mark class=\"m-destacable\">del</mark> artículo <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">76</mark> la pena a cumplir resultase inferior a la mitad de la suma total de las impuestas, el <mark class=\"m-autoridad\">juez o tribunal sentenciador</mark> <mark class=\"m-accion\">podrá acordar</mark> <mark class=\"m-autoridad\">que los beneficios</mark> <mark class=\"m-personalizado\">penitenciarios, los permisos de salida,</mark> la <mark class=\"m-personalizado\">clasificación</mark> en tercer grado y el cómputo de tiempo para la <mark class=\"m-personalizado\">libertad condicional</mark> <mark class=\"m-destacable\">se refieran a</mark> la <mark class=\"m-destacable\">totalidad</mark> de las penas impuestas en las sentencias.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1331\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.</b> En estos casos, el <mark class=\"m-autoridad\">juez</mark> de vigilancia, <mark class=\"m-personalizado\">previo pronóstico</mark> individualizado y <mark class=\"m-personalizado\">favorable</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de reinserción social y valorando, en su caso, las circunstancias personales del reo y la evolución</span></span> del tratamiento reeducador, <mark class=\"m-accion\">podrá acordar</mark> <mark class=\"m-autoridad\">razonadamente, oídos el Ministerio Fiscal, Instituciones Penitenciarias y las demás partes,</mark> la aplicación del <mark class=\"m-destacable\">régimen general de cumplimiento.</mark></p><p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-destacable\">Al</mark> <mark class=\"m-plazo\">tercer grado</mark> penitenciario, cuando quede por cumplir <mark class=\"m-resp r-ia\" data-q=\"18-ia-1332\">una quinta parte del límite máximo de cumplimiento de la condena</mark>.</p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-destacable\">A la libertad condicional,</mark> <mark class=\"m-plazo\">cuando</mark> quede por cumplir <mark class=\"m-resp r-ia\" data-q=\"18-ia-1333\">una octava parte del límite <mark class=\"m-plazo\">máximo de cumplimiento</mark> de la condena</mark>.</p></div></div><div class=\"trampa\"><b>⚠ Cifras que se confunden</b><p><em><mark class=\"m-personalizado\">Prisión</mark> <u class=\"m-clave\">permanente</u> revisable con <mark class=\"m-personalizado\">otras penas</mark> (art. <u class=\"m-clave\">78 bis</u>)</em><strong><u class=\"m-clave\">Tercer</u> <mark class=\"m-personalizado\">grado</mark>: 18 <mark class=\"m-plazo\">años</mark> (<mark class=\"m-personalizado\">resto</mark> > 5 <mark class=\"m-plazo\">años</mark>), 20 <mark class=\"m-plazo\">años</mark> (<mark class=\"m-personalizado\">resto</mark> > 15), 22 <mark class=\"m-plazo\">años</mark> (<mark class=\"m-personalizado\">dos</mark> permanentes, o una más 25 <mark class=\"m-plazo\">años</mark> o más) · <mark class=\"m-personalizado\">suspensión</mark>: 25 <mark class=\"m-plazo\">años</mark> (letras a y b) o 30 <mark class=\"m-plazo\">años</mark> (<mark class=\"m-personalizado\">letra</mark> c)</strong> — <u class=\"m-clave\">no</u> 18 <mark class=\"m-plazo\">años</mark> <mark class=\"m-personalizado\">si</mark> <mark class=\"m-personalizado\">el resto</mark> excede de 15 · <u class=\"m-clave\">no</u> 22 <mark class=\"m-plazo\">años</mark> con una sola <u class=\"m-clave\">permanente</u> y 10 <mark class=\"m-plazo\">años</mark> de <mark class=\"m-personalizado\">resto</mark> · <u class=\"m-clave\">no</u> <mark class=\"m-personalizado\">suspensión</mark> a los 20 <mark class=\"m-plazo\">años</mark></p></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> <u class=\"m-clave\">78 bis</u>: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1110,18-ia-1334,18-ia-1335,18-ia-1336,18-ia-1337,18-ia-1338\">🎯 6 preguntas más de este artículo</mark>"],["Artículo 96 <span class=\"ex-sello\">EX</span>","<p><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Las medidas de seguridad que se pueden imponer con arreglo</span></span> a este Código <mark class=\"m-personalizado\">son privativas y</mark> no privativas de libertad. <mark class=\"m-resp ex-q\" data-q=\"18-158\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>2.</b> Son medidas <mark class=\"m-destacable\">privativas de</mark> libertad: <mark class=\"m-resp ex-q\" data-q=\"18-277\">🎯 1 pregunta</mark></p><p><b>2.ª</b> El <mark class=\"m-autoridad\">internamiento</mark> en <mark class=\"m-personalizado\">centro de deshabituación.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1343\">🎯 1 pregunta</mark></p><p><b>3.ª</b> El <mark class=\"m-autoridad\">internamiento</mark> en <mark class=\"m-personalizado\">centro educativo especial.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-235\">🎯 1 pregunta</mark></p><p><mark class=\"m-destacable\">3.ª)</mark> <mark class=\"m-personalizado\">La <mark class=\"m-resp r-ia\" data-q=\"18-ia-1342\">libertad vigilada</mark></mark></p><p>4.ª) <mark class=\"m-personalizado\">La custodia familiar.</mark> El sometido a <span class=\"ex-plg\"><span class=\"ex-plg-t\">esta medida <mark class=\"m-accion\">quedará</mark> sujeto al cuidado y vigilancia del familiar que se designe y que acepte la custodia, quien <mark class=\"m-accion\">la ejercerá</mark> en relación con <mark class=\"m-autoridad\">el Juez de Vigilancia Penitenciaria y sin menoscabo</mark> de las actividades escolares o laborales del custodiado.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1344\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>MEDIDAS DE SEGURIDAD (cuadro del temario · art. 96)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>PRIVATIVAS DE LIBERTAD</h5><ul><li>El <mark class=\"m-autoridad\">internamiento</mark> <mark class=\"m-personalizado\">en centro psiquiátrico</mark>.</li><li>El <mark class=\"m-autoridad\">internamiento</mark> en <mark class=\"m-personalizado\">centro de deshabituación</mark>.</li><li>El <mark class=\"m-autoridad\">internamiento</mark> en <mark class=\"m-personalizado\">centro educativo especial</mark>.</li></ul></div><div class=\"vis-col\"><h5>NO PRIVATIVAS DE LIBERTAD</h5><ul><li>La <u class=\"m-clave\">inhabilitación</u> profesional.</li><li><mark class=\"m-personalizado\">La expulsión del territorio</mark> nacional de <mark class=\"m-autoridad\">extranjeros</mark> <u class=\"m-clave\">no residentes legalmente</u> en España.</li><li><mark class=\"m-personalizado\">La libertad vigilada</mark>.</li><li><mark class=\"m-personalizado\">La custodia familiar</mark>.</li><li>La <u class=\"m-clave\">privación</u> <mark class=\"m-personalizado\">del derecho a conducir</mark> <mark class=\"m-personalizado\">vehículos a motor y ciclomotores</mark>.</li><li>La <u class=\"m-clave\">privación</u> del <mark class=\"m-personalizado\">derecho</mark> a <mark class=\"m-personalizado\">la tenencia y porte de armas</mark>.</li></ul></div></div></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Art. 97 CP · Durante la ejecución de la sentencia (cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-paso o\"><span class=\"et\">Quién y cuándo</span>Respecto a <mark class=\"m-destacable\">las medidas de seguridad</mark> <mark class=\"m-personalizado\">impuestas</mark>, <mark class=\"m-autoridad\">el Juez o Tribunal sentenciador</mark> <mark class=\"m-accion\">adoptará</mark> <u class=\"m-clave\">alguna</u> de <mark class=\"m-personalizado\">las siguientes</mark> decisiones <u class=\"m-clave\">durante la</u> <mark class=\"m-destacable\">ejecución</mark> de <mark class=\"m-personalizado\">la sentencia</mark>:</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso v\"><span class=\"et\">MANTENER</span><mark class=\"m-personalizado\">Mantener</mark> <mark class=\"m-personalizado\">la ejecución</mark> de la <u class=\"m-clave\">medida</u> de seguridad impuesta.</div><div class=\"vis-paso c\"><span class=\"et\">DECRETAR EL CESE</span><mark class=\"m-personalizado\">Decretar el</mark> cese en cuanto desaparezca la peligrosidad <u class=\"m-clave\">criminal</u> del sujeto.</div></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso o\"><span class=\"et\">SUSTITUIR</span><mark class=\"m-personalizado\">Sustituir</mark> la <u class=\"m-clave\">medida</u> por otra que estime más adecuada, pero <mark class=\"m-personalizado\">en el caso de</mark>: <mark class=\"m-personalizado\">sustituir</mark> la <u class=\"m-clave\">medida</u> + evolución desfavorable del sujeto = dejar <u class=\"m-clave\">sin efecto</u> <mark class=\"m-personalizado\">la sustitución</mark> y volver a aplicar la <u class=\"m-clave\">medida</u> sustituida.</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso v\"><span class=\"et\">DEJAR EN SUSPENSO</span><mark class=\"m-personalizado\">Dejar en suspenso la ejecución</mark> de la <u class=\"m-clave\">medida</u>: atendiendo al <u class=\"m-clave\">resultado</u> ya obtenido con la aplicación de la <u class=\"m-clave\">medida</u> · <u class=\"m-clave\">suspensión por un plazo no superior</u> al que reste <mark class=\"m-personalizado\">hasta</mark> <mark class=\"m-destacable\">el máximo</mark> señalado en <mark class=\"m-personalizado\">la sentencia</mark> que la impuso · <u class=\"m-clave\">condicionada a que el sujeto no delinca</u> <mark class=\"m-personalizado\">durante</mark> el plazo fijado (queda <u class=\"m-clave\">sin efecto</u> la <mark class=\"m-personalizado\">suspensión</mark> <mark class=\"m-personalizado\">cuando</mark> se constate <u class=\"m-clave\">alguna</u> de <mark class=\"m-personalizado\">las circunstancias</mark> del art. 95 CP).</div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 97: <mark class=\"m-resp ex-q\" data-q=\"18-160,18-ia-1345,18-ia-1401,18-ia-1402\">🎯 4 preguntas más de este artículo</mark></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Art. 98 CP · Cuando una medida de seguridad deba ejecutarse DESPUÉS del cumplimiento de una pena privativa de libertad (cuadro del temario)</div><div class=\"vis-flujo\"><div class=\"vis-bifurca\"><div class=\"vis-paso o\"><span class=\"et\">MEDIDA PRIVATIVA DE LIBERTAD o LIBERTAD VIGILADA</span><mark class=\"m-autoridad\">JUEZ DE VIGILANCIA PENITENCIARIA</mark>: <mark class=\"m-personalizado\">obligado</mark> a elevar <mark class=\"m-plazo\">al <u class=\"m-clave\">menos</u> anualmente</mark> <mark class=\"m-personalizado\">propuesta de mantenimiento, cese, sustitución</mark> o <mark class=\"m-destacable\">suspensión de</mark> la <u class=\"m-clave\">medida</u>. Debiendo valorar: <mark class=\"m-personalizado\">informes</mark> de los facultativos · <mark class=\"m-personalizado\">informes</mark> de los profesionales que asistan al sometido a <u class=\"m-clave\">medida</u> de seguridad · <mark class=\"m-personalizado\">informes</mark> por las Administraciones Públicas competentes · resultados de <mark class=\"m-personalizado\">demás actuaciones</mark> que a este fin ordene.</div><div class=\"vis-paso v\"><span class=\"et\">CUALQUIER OTRA MEDIDA NO PRIVATIVA DE LIBERTAD</span><mark class=\"m-autoridad\">JUEZ o TRIBUNAL SENTENCIADOR</mark> <mark class=\"m-accion\">recabará</mark> <mark class=\"m-personalizado\">directamente</mark> de <mark class=\"m-autoridad\">las Administraciones, facultativos y profesionales</mark> los oportunos <mark class=\"m-personalizado\">informes</mark> acerca de la situación y evolución del <mark class=\"m-personalizado\">condenado</mark>, su <mark class=\"m-personalizado\">grado</mark> de rehabilitación y el <mark class=\"m-personalizado\">pronóstico</mark> de reincidencia o <u class=\"m-clave\">reiteración</u> <u class=\"m-clave\">delictiva</u>.</div></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso c\"><span class=\"et\">En todo caso</span><mark class=\"m-autoridad\">El Juez o Tribunal sentenciador</mark> <mark class=\"m-accion\">resolverá</mark> motivadamente <mark class=\"m-personalizado\">a la vista de</mark> <mark class=\"m-personalizado\">la propuesta</mark> del JVP o <mark class=\"m-personalizado\">los informes</mark> · oirá a la <mark class=\"m-autoridad\">persona</mark> sometida a la <u class=\"m-clave\">medida</u>, <mark class=\"m-autoridad\">al Ministerio Fiscal</mark> y <mark class=\"m-autoridad\">demás partes</mark> · <mark class=\"m-accion\">se oirá</mark> a <mark class=\"m-autoridad\">las víctimas</mark> del <mark class=\"m-personalizado\">delito</mark> que <u class=\"m-clave\">no</u> estuvieren <mark class=\"m-personalizado\">personadas</mark> <mark class=\"m-personalizado\">cuando</mark> así lo hubieran solicitado al inicio o en cualquier momento de <mark class=\"m-personalizado\">la ejecución</mark> de <mark class=\"m-personalizado\">la sentencia</mark> y permanezcan localizables a <mark class=\"m-personalizado\">tal efecto</mark>.</div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 98: <mark class=\"m-resp ex-q\" data-q=\"18-64,18-80,18-120,18-234,18-ia-1403,18-ia-1404,18-ia-1405\">🎯 7 preguntas más de este artículo</mark>"],["Artículo 105 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\">En los casos previstos en los artículos <mark class=\"m-personalizado\">101 a 104, <u class=\"m-clave\">cuando</u> imponga</mark> la <mark class=\"m-personalizado\">medida privativa <u class=\"m-clave\">de libertad</u></mark> o <mark class=\"m-personalizado\"><u class=\"m-clave\">durante la</u> ejecución</mark> de la misma, <mark class=\"m-autoridad\">el Juez o Tribunal</mark> <mark class=\"m-accion\">podrá imponer</mark> razonadamente <mark class=\"m-destacable\"><u class=\"m-clave\">una</u> o <u class=\"m-clave\">varias</u></mark> <mark class=\"m-personalizado\">medidas que se</mark> enumeran <mark class=\"m-personalizado\">a continuación.</mark> <mark class=\"m-accion\">Deberá</mark> <mark class=\"m-personalizado\">asimismo</mark> imponer alguna o algunas de dichas medidas <mark class=\"m-personalizado\">en los demás casos</mark> expresamente <mark class=\"m-personalizado\">previstos</mark> en este <mark class=\"m-personalizado\">Código.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-278\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF\"><b>1.</b> Por un tiempo no superior a cinco años:</p><p style=\"margin-left:18px\"><b>b)</b> <mark class=\"m-personalizado\">Custodia familiar.</mark> El sometido a <span class=\"ex-plg\"><span class=\"ex-plg-t\">esta medida <mark class=\"m-accion\">quedará</mark> sujeto al cuidado y vigilancia del <mark class=\"m-personalizado\">familiar</mark> que se designe y que acepte la custodia, quien la <mark class=\"m-accion\">ejercerá</mark> en relación con el <mark class=\"m-autoridad\">Juez</mark> de Vigilancia y sin menoscabo de las actividades escolares o laborales del custodiado.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1418\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF\"><b>2.</b> <mark class=\"m-autoridad\">Por un</mark> <mark class=\"m-plazo\">tiempo de hasta diez años:</mark> <mark class=\"m-resp ex-q\" data-q=\"18-279\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>a)</b> <mark class=\"m-personalizado\">Libertad vigilada,</mark> cuando <mark class=\"m-personalizado\"><u class=\"m-clave\">expresamente</u> lo disponga este Código.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1419\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>b)</b> La privación del derecho a <mark class=\"m-personalizado\">la tenencia y porte de armas.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-47\">🎯 1 pregunta</mark></p>"],["Artículo 108 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R24</span>","<p data-ex=\"EXOF\"><b>1.</b> Si el sujeto fuera <mark class=\"m-autoridad\">extranjero</mark> <mark class=\"m-resp\" data-q=\"18-29\">no <mark class=\"m-destacable\">residente</mark> <mark class=\"m-personalizado\">legalmente</mark> en España</mark>, <mark class=\"m-autoridad\">el juez o tribunal</mark> <mark class=\"m-accion\">acordará</mark> en la sentencia, previa <mark class=\"m-autoridad\">audiencia</mark> de aquél, la expulsión del territorio nacional <mark class=\"m-personalizado\">como sustitutiva de las medidas de seguridad</mark> que le sean aplicables, salvo que el <mark class=\"m-autoridad\">juez o tribunal,</mark> <mark class=\"m-personalizado\">previa</mark> <mark class=\"m-autoridad\">audiencia del Ministerio Fiscal,</mark> <mark class=\"m-destacable\">excepcionalmente y</mark> de forma <span class=\"m-caja\">motivada,</span> aprecie que la naturaleza del delito <mark class=\"m-personalizado\">justifica el cumplimiento en España.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-74,18-ia-1427\">🎯 2 preguntas</mark></p><p>En el supuesto de que, <span class=\"ex-plg\"><span class=\"ex-plg-t\">acordada la sustitución de la medida de seguridad por <mark class=\"m-personalizado\">la expulsión,</mark> ésta <mark class=\"m-personalizado\">no pudiera llevarse</mark> a efecto, <mark class=\"m-accion\">se procederá</mark> <mark class=\"m-personalizado\">al cumplimiento de la medida</mark> de seguridad originariamente impuesta.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1428\">🎯 1 pregunta</mark></p><p data-ex=\"EX\" data-r=\"R24\"><span class=\"ex-sello ex-sello-r\">R24</span> <b>2.</b> El <mark class=\"m-autoridad\">extranjero</mark> <mark class=\"m-accion\">no podrá regresar</mark> a España <mark class=\"m-plazo\">en un plazo de 10 años, contados desde la fecha</mark> de su expulsión.</p><p><b>3.</b> El <mark class=\"m-autoridad\">extranjero</mark> que <mark class=\"m-personalizado\">intentara quebrantar</mark> una decisión judicial de <u class=\"m-clave\">expulsión y</u> <mark class=\"m-personalizado\"><u class=\"m-clave\">prohibición</u> de entrada</mark> a la que se refieren <mark class=\"m-personalizado\">los apartados</mark> anteriores <mark class=\"m-accion\">será devuelto</mark> <mark class=\"m-personalizado\">por la</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">autoridad</u></mark> <mark class=\"m-personalizado\">gubernativa, empezando a computarse de nuevo el plazo</mark> de prohibición de entrada <mark class=\"m-personalizado\">en su integridad.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1430\">🎯 1 pregunta</mark></p>"],["Artículo 109","<p><b>1.</b> <mark class=\"m-personalizado\">La ejecución</mark> de un hecho descrito <span class=\"ex-plg\"><span class=\"ex-plg-t\">por la ley como <mark class=\"m-personalizado\">delito</mark> <mark class=\"m-destacable\">obliga a reparar,</mark> en los términos previstos <mark class=\"m-personalizado\">en las leyes, los daños y perjuicios</mark> por él causados.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1431\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-autoridad\">El perjudicado</mark> <mark class=\"m-accion\">podrá optar,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">en todo caso,</u> por exigir la responsabilidad civil</mark> <mark class=\"m-autoridad\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1432\">ante la Jurisdicción Civil</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-161\">🎯 1 pregunta</mark></p>"],["Artículo 111 <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">Deberá restituirse,</mark> <mark class=\"m-autoridad\">siempre</mark> que sea posible, el <mark class=\"m-personalizado\">mismo bien,</mark> con <mark class=\"m-personalizado\">abono de los deterioros</mark> y menoscabos que el <mark class=\"m-autoridad\">juez o tribunal</mark> determinen.</span></span> La restitución <mark class=\"m-accion\">tendrá</mark> lugar aunque el <span class=\"ex-plg\"><span class=\"ex-plg-t\">bien <mark class=\"m-personalizado\">se halle</mark> en poder de tercero y éste lo haya adquirido legalmente y de</span></span> buena fe, dejando a salvo <mark class=\"m-resp r-ia\" data-q=\"18-ia-1434\">su derecho de repetición contra quien corresponda y, en su caso, el de ser indemnizado por el responsable civil del delito</mark>. <mark class=\"m-resp ex-q\" data-q=\"18-123\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>2.</b> Esta disposición <mark class=\"m-destacable\"><u class=\"m-clave\">no</u> es <u class=\"m-clave\">aplicable</u></mark> cuando <mark class=\"m-autoridad\">el tercero</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">haya adquirido</mark> el <mark class=\"m-destacable\">bien</mark> en <mark class=\"m-personalizado\">la forma y</mark> con los <mark class=\"m-personalizado\">requisitos establecidos</mark> por <mark class=\"m-personalizado\">las Leyes para</mark> <mark class=\"m-destacable\">hacerlo irreivindicable.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-284\">🎯 1 pregunta</mark></p>"],["Artículo 112","<p><mark class=\"m-destacable\">La reparación</mark> del daño <mark class=\"m-accion\">podrá consistir</mark> en <mark class=\"m-resp r-ia\" data-q=\"18-ia-1435\">obligaciones <mark class=\"m-destacable\">de dar, de hacer o de</mark> no <mark class=\"m-destacable\">hacer</mark> <mark class=\"m-personalizado\">que</mark> el <mark class=\"m-autoridad\">Juez o Tribunal</mark> <mark class=\"m-accion\">establecerá</mark> <mark class=\"m-personalizado\">atendiendo a la naturaleza</mark> de aquél <mark class=\"m-personalizado\">y</mark> a <mark class=\"m-personalizado\">las condiciones personales y patrimoniales</mark> del culpable</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">determinando si han de <mark class=\"m-personalizado\">ser cumplidas por él</mark> mismo o <mark class=\"m-personalizado\">pueden</mark> ser ejecutadas <mark class=\"m-personalizado\">a su costa.</mark></span></span> <mark class=\"m-resp ex-q\" data-q=\"18-15,18-21\">🎯 2 preguntas</mark></p>"],["Artículo 113","<p><mark class=\"m-plazo\">La</mark> <mark class=\"m-destacable\">indemnización de</mark> <mark class=\"m-personalizado\">perjuicios materiales y morales</mark> <mark class=\"m-accion\">comprenderá</mark> no sólo los que <mark class=\"m-personalizado\">se</mark> hubieren causado <mark class=\"m-autoridad\">al agraviado,</mark> sino también los <mark class=\"m-resp r-ia\" data-q=\"18-ia-1436\">que se hubieren irrogado a sus familiares o a terceros</mark>. <mark class=\"m-resp ex-q\" data-q=\"18-152\">🎯 1 pregunta</mark></p>"],["Artículo 114","<p><mark class=\"m-personalizado\">Si la</mark> <mark class=\"m-autoridad\">víctima</mark> <mark class=\"m-accion\">hubiere</mark> <mark class=\"m-personalizado\">contribuido</mark> con su conducta a la <mark class=\"m-personalizado\">producción del daño o perjuicio</mark> sufrido, los <mark class=\"m-autoridad\">Jueces o Tribunales</mark> <mark class=\"m-accion\">podrán moderar</mark> el importe de su <mark class=\"m-personalizado\">reparación o indemnización.</mark>  <mark class=\"m-resp ex-q\" data-q=\"18-28,18-145,18-ia-1437\">🎯 3 preguntas</mark></p>"],["Artículo 115","<p><mark class=\"m-autoridad\">Los Jueces y Tribunales,</mark> <mark class=\"m-personalizado\">al declarar</mark> la existencia de <mark class=\"m-personalizado\">responsabilidad civil,</mark> <mark class=\"m-accion\">establecerán</mark> <mark class=\"m-personalizado\">razonadamente,</mark> <mark class=\"m-autoridad\">en sus</mark> resoluciones <mark class=\"m-personalizado\"><u class=\"m-clave\">las</u> bases en que fundamenten <u class=\"m-clave\">la</u> cuantía</mark> de los daños e indemnizaciones, <mark class=\"m-personalizado\">pudiendo fijarla en la propia resolución o en</mark> el momento <mark class=\"m-personalizado\">de su ejecución.</mark>  <mark class=\"m-resp ex-q\" data-q=\"18-5,18-139\">🎯 2 preguntas</mark></p>"],["Artículo 116","<p><b>1.</b> <mark class=\"m-personalizado\">Toda</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">criminalmente responsable</mark> de un delito <mark class=\"m-personalizado\">lo es también civilmente</mark> si del hecho se <mark class=\"m-personalizado\">derivaren daños o perjuicios.</mark> Si son <mark class=\"m-personalizado\">dos o más</mark> los responsables de un delito <mark class=\"m-autoridad\">los jueces o tribunales</mark> <mark class=\"m-accion\">señalarán</mark> <mark class=\"m-personalizado\">la cuota</mark> de que deba responder <mark class=\"m-personalizado\">cada uno.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-8,18-ia-1438\">🎯 2 preguntas</mark></p><p data-ex=\"EXAMEN\"><b>2.</b> <mark class=\"m-autoridad\"><u class=\"m-clave\">Los</u> autores y los cómplices,</mark> cada <u class=\"m-clave\">uno dentro de su</u> respectiva clase, <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">responsables <u class=\"m-clave\">solidariamente</u> entre</mark> sí por sus cuotas, y subsidiariamente <mark class=\"m-personalizado\">por</mark> las correspondientes a los <mark class=\"m-personalizado\">demás</mark> responsables. <mark class=\"m-resp ex-q\" data-q=\"18-17,18-42,18-ia-1439\">🎯 3 preguntas</mark></p><p><mark class=\"m-destacable\"><u class=\"m-clave\">La responsabilidad subsidiaria</u></mark> <mark class=\"m-accion\">se hará</mark> <mark class=\"m-personalizado\">efectiva: <u class=\"m-clave\">primero,</u></mark> <mark class=\"m-destacable\">en los bienes</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">los <mark class=\"m-autoridad\">autores,</mark> <mark class=\"m-destacable\">y</mark> <mark class=\"m-personalizado\">después, en los</mark> de los <mark class=\"m-autoridad\">cómplices.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1440\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">La responsabilidad penal de una</mark> <mark class=\"m-autoridad\">persona</mark> jurídica <mark class=\"m-accion\">llevará</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">consigo <u class=\"m-clave\">su</u> responsabilidad <mark class=\"m-personalizado\">civil</mark> en los <mark class=\"m-personalizado\">términos establecidos</mark> en el artículo 110 de este Código <mark class=\"m-personalizado\">de forma solidaria con las</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">físicas</mark> que fueren <mark class=\"m-personalizado\">condenadas</mark> por los mismos hechos.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1441\">🎯 1 pregunta</mark></p>"],["Artículo 118 <span class=\"ex-sello\">✱</span>","<p><b>1.ª</b> En los casos de los <span class=\"ex-plg\"><span class=\"ex-plg-t\">números 1.º y <mark class=\"m-personalizado\">3.º,</mark> son <mark class=\"m-personalizado\">también responsables</mark> por los <mark class=\"m-personalizado\">hechos que</mark> ejecuten los declarados exentos de</span></span> responsabilidad penal, <mark class=\"m-personalizado\">quienes ejerzan</mark> su <mark class=\"m-personalizado\">apoyo legal o de hecho, siempre que</mark> <mark class=\"m-resp r-ia\" data-q=\"18-ia-1443\">haya mediado <mark class=\"m-personalizado\"><u class=\"m-clave\">culpa</u> o negligencia por su parte y sin perjuicio</mark> de <mark class=\"m-personalizado\">la responsabilidad civil directa</mark> que pudiera <mark class=\"m-personalizado\">corresponder a</mark> los inimputables</mark>.</p><p data-ex=\"*\"><b>4.ª</b> En el caso del número <span class=\"ex-plg\"><span class=\"ex-plg-t\">6.º, <mark class=\"m-accion\">responderán</mark> <mark class=\"m-personalizado\">principalmente los que hayan causado el miedo, y en defecto de ellos, los que hayan ejecutado</mark> el <mark class=\"m-personalizado\">hecho.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-285\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 119: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1444\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 120","<p data-ex=\"EXAMEN\"><mark class=\"m-personalizado\">Son también responsables civilmente, en defecto de los que lo sean criminalmente:</mark></p><p><b>1.º</b> <mark class=\"m-personalizado\">Los curadores con facultades de representación plena que convivan</mark> con la <mark class=\"m-autoridad\">persona</mark> a <mark class=\"m-personalizado\">quien</mark> prestan <mark class=\"m-personalizado\">apoyo, siempre que haya</mark> por su parte <mark class=\"m-personalizado\">culpa o negligencia.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-13,18-286\">🎯 2 preguntas</mark></p><p><b>2.º</b> Las <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">naturales o jurídicas titulares de editoriales, periódicos, revistas, estaciones de radio o</mark> televisión <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">o</u></mark> de <mark class=\"m-personalizado\">cualquier otro medio de difusión</mark> escrita, hablada o visual, <mark class=\"m-personalizado\">por los delitos</mark> cometidos <mark class=\"m-personalizado\">utilizando los medios</mark> de los que sean titulares, dejando a salvo lo dispuesto en el artículo 212.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1445\">🎯 1 pregunta</mark></p><p><b>3.º</b> <mark class=\"m-personalizado\">Las</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">naturales o jurídicas,</mark> en los casos de delitos cometidos <mark class=\"m-personalizado\">en los establecimientos de los que sean titulares, cuando</mark> por parte de los que los <mark class=\"m-personalizado\">dirijan</mark> o administren, o de <mark class=\"m-personalizado\">sus dependientes o empleados, se hayan infringido los reglamentos de policía</mark> o las disposiciones de la <mark class=\"m-autoridad\">autoridad</mark> que estén relacionados <mark class=\"m-personalizado\">con</mark> el hecho punible cometido, de modo que éste no <mark class=\"m-personalizado\">se hubiera producido sin dicha infracción.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-81,18-102\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 121: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1446,18-ia-1447\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 127","<p><b>1.</b> <mark class=\"m-personalizado\">Toda pena</mark> que se imponga por <span class=\"ex-plg\"><span class=\"ex-plg-t\">un <mark class=\"m-personalizado\">delito doloso</mark> <mark class=\"m-accion\">llevará</mark> <mark class=\"m-personalizado\">consigo la pérdida de los efectos que de él provengan y de los bienes, medios o instrumentos</mark> con que <mark class=\"m-personalizado\">se</mark> haya <mark class=\"m-personalizado\">preparado o ejecutado, así como de las ganancias provenientes del delito, cualesquiera</mark> que sean las <mark class=\"m-personalizado\">transformaciones</mark> que hubieren podido experimentar.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1502\">🎯 1 pregunta</mark></p><p><b>2.</b> En los casos en que la ley prevea la imposición <mark class=\"m-personalizado\">de una pena privativa de libertad superior a un año por la</mark> <mark class=\"m-autoridad\">comisión</mark> <mark class=\"m-personalizado\">de un delito imprudente, el</mark> <mark class=\"m-autoridad\">juez o tribunal</mark> <mark class=\"m-accion\">podrá acordar</mark> <mark class=\"m-personalizado\">la pérdida de los efectos que provengan del mismo y de los bienes, medios o instrumentos con que se haya preparado o ejecutado, así como de las ganancias provenientes del</mark> delito, cualesquiera que sean las <mark class=\"m-personalizado\">transformaciones</mark> que hubieran podido <mark class=\"m-personalizado\">experimentar.</mark>  <mark class=\"m-resp ex-q\" data-q=\"18-122,18-ia-1503\">🎯 2 preguntas</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">Si</mark> por cualquier circunstancia <mark class=\"m-personalizado\">no fuera posible el decomiso de los bienes señalados en los apartados anteriores de este artículo,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">se acordará</mark> <mark class=\"m-personalizado\">el decomiso de otros bienes</mark> por una cantidad que corresponda al valor económico de los mismos, y al de las ganancias que se <mark class=\"m-personalizado\">hubieran obtenido de ellos. De igual modo</mark> <mark class=\"m-accion\">se procederá</mark> cuando se acuerde el <mark class=\"m-personalizado\">decomiso</mark> de bienes, efectos o ganancias <mark class=\"m-personalizado\">determinados, pero su valor</mark> sea <mark class=\"m-personalizado\"><u class=\"m-clave\">inferior</u> al que tenían</mark> en el momento de su adquisición.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1504\">🎯 1 pregunta</mark></p>"],["Artículo 127 bis <span class=\"ex-sello\">✱</span>","<p><b><mark class=\"m-personalizado\">1.</mark></b> <mark class=\"m-personalizado\">El</mark> <mark class=\"m-autoridad\">juez o tribunal</mark> <mark class=\"m-accion\">ordenará</mark> <mark class=\"m-personalizado\">también el decomiso de los bienes, efectos y ganancias pertenecientes a una</mark> <mark class=\"m-autoridad\">persona</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">condenada por alguno de los siguientes delitos cuando resuelva, a partir de indicios objetivos fundados, que los bienes o efectos provienen de una actividad delictiva, y <mark class=\"m-resp r-ia\" data-q=\"18-ia-1505\">no se acredite su origen lícito</mark>:</mark></span></span></p><p style=\"margin-left:18px\" data-ex=\"*\"><b>d)</b> Delitos <mark class=\"m-personalizado\">contra el patrimonio</mark> y contra el <span class=\"ex-plg\"><span class=\"ex-plg-t\">orden socioeconómico en los <mark class=\"m-personalizado\">supuestos de continuidad delictiva y reincidencia.</mark></span></span>  <mark class=\"m-resp ex-q\" data-q=\"18-287\">🎯 1 pregunta</mark></p><p><b>2.º</b> <mark class=\"m-destacable\"><u class=\"m-clave\">La</u></mark> <mark class=\"m-personalizado\">ocultación <u class=\"m-clave\">de</u> la titularidad o</mark> de cualquier poder <span class=\"ex-plg\"><span class=\"ex-plg-t\">de disposición sobre los bienes o efectos mediante la <mark class=\"m-personalizado\">utilización de</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">físicas o jurídicas</mark> o entes sin personalidad jurídica interpuestos, o <mark class=\"m-personalizado\">paraísos</mark> <mark class=\"m-autoridad\">fiscales</mark> o territorios de nula tributación que <mark class=\"m-personalizado\">oculten o dificulten la determinación</mark> de la <mark class=\"m-personalizado\">verdadera titularidad</mark> de los bienes.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1507\">🎯 1 pregunta</mark></p><p><b>5.</b> El decomiso a que se <span class=\"ex-plg\"><span class=\"ex-plg-t\">refiere este artículo <mark class=\"m-accion\">no será acordado</mark> cuando las actividades delictivas de las que</span></span> provengan los bienes o efectos <mark class=\"m-resp r-ia\" data-q=\"18-ia-1508\">hubieran prescrito o hubieran sido ya objeto de un proceso penal resuelto por <mark class=\"m-personalizado\">sentencia absolutoria</mark> o resolución de <mark class=\"m-personalizado\">sobreseimiento</mark> con efectos de cosa juzgada</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 127</mark> ter: <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1509,18-ia-1510\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 130 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R26</span>","<p data-ex=\"EXOF\"><b>1.</b> <mark class=\"m-personalizado\">La responsabilidad criminal se</mark> <mark class=\"m-destacable\">extingue:</mark> <mark class=\"m-resp ex-q\" data-q=\"18-289\">🎯 1 pregunta</mark></p><p data-ex=\"EXAMEN\"><b>5.º</b> Por el <mark class=\"m-destacable\">perdón</mark> <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">ofendida,</mark> cuando se trate de <span class=\"m-circulo\"><mark class=\"m-personalizado\">delitos leves</mark></span> <mark class=\"m-personalizado\">perseguibles a</mark> instancias de la <mark class=\"m-autoridad\">persona</mark> agraviada o la ley <mark class=\"m-personalizado\">así lo prevea. El perdón</mark> <mark class=\"m-accion\">habrá</mark> de ser otorgado de <mark class=\"m-personalizado\">forma expresa</mark> <mark class=\"m-plazo\">antes de que se haya dictado sentencia,</mark> a cuyo efecto la <mark class=\"m-autoridad\">autoridad</mark> judicial <mark class=\"m-personalizado\">sentenciadora</mark> <mark class=\"m-accion\">deberá</mark> oír a la <mark class=\"m-autoridad\">persona</mark> ofendida por el delito antes de dictarla. <mark class=\"m-resp ex-q\" data-q=\"18-116,18-ia-1529\">🎯 2 preguntas</mark></p><p>En los <mark class=\"m-personalizado\">delitos</mark> cometidos <mark class=\"m-personalizado\">contra</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">personas <u class=\"m-clave\">menores</u></mark> <mark class=\"m-personalizado\">de edad <u class=\"m-clave\">o</u></mark> <mark class=\"m-autoridad\">personas</mark> con <mark class=\"m-personalizado\">discapacidad necesitadas de especial protección</mark> que <mark class=\"m-personalizado\">afecten a bienes jurídicos eminentemente personales, el perdón de la</mark> <mark class=\"m-autoridad\">persona</mark> ofendida <mark class=\"m-personalizado\">no extingue la responsabilidad</mark> criminal.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1530\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">La</mark> <mark class=\"m-autoridad\">transformación, fusión, absorción o escisión de una persona jurídica no</mark> <mark class=\"m-destacable\">extingue</mark> <mark class=\"m-personalizado\">su responsabilidad <u class=\"m-clave\">penal,</u> que</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">se trasladará</mark> <mark class=\"m-personalizado\">a la entidad</mark> o entidades en <mark class=\"m-personalizado\">que se transforme,</mark> quede fusionada o absorbida <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">se extenderá</mark> a la entidad o entidades que resulten de la escisión. <mark class=\"m-autoridad\">El Juez o Tribunal</mark> <mark class=\"m-accion\">podrá moderar</mark> <mark class=\"m-personalizado\">el traslado de la pena</mark> a la <mark class=\"m-autoridad\">persona</mark> jurídica <mark class=\"m-personalizado\">en función de la proporción</mark> que la <mark class=\"m-autoridad\">persona</mark> jurídica originariamente responsable del delito guarde con ella.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1531\">🎯 1 pregunta</mark></p><p data-r=\"R26\"><span class=\"ex-sello ex-sello-r\">R26</span> <mark class=\"m-destacable\">No extingue</mark> la responsabilidad penal la <mark class=\"m-autoridad\">disolución <u class=\"m-clave\">encubierta</u> o meramente aparente</mark> <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">jurídica.</mark> <mark class=\"m-accion\">Se considerará</mark> <mark class=\"m-destacable\">en todo caso</mark> que existe <mark class=\"m-personalizado\">disolución encubierta</mark> o <mark class=\"m-personalizado\">meramente aparente</mark> de la <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">jurídica cuando se continúe su actividad económica y se mantenga</mark> la <mark class=\"m-personalizado\">identidad</mark> sustancial de <mark class=\"m-personalizado\">clientes, proveedores y empleados,</mark> o de la <mark class=\"m-personalizado\">parte más relevante</mark> de todos ellos. <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1532\">🎯 1 pregunta</mark></p>"],["Artículo 131 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R27</span> <span class=\"ex-sello ex-sello-r\">R28</span>","<p data-ex=\"EXAMEN,EXOF\"><b>1.</b> Los <mark class=\"m-destacable\">delitos prescriben:</mark> <mark class=\"m-resp ex-q\" data-q=\"18-291\">🎯 1 pregunta</mark></p><p><mark class=\"m-plazo\">A los veinte años,</mark> cuando la <mark class=\"m-personalizado\">pena máxima</mark> señalada al delito <mark class=\"m-personalizado\">sea <mark class=\"m-resp r-ia\" data-q=\"18-ia-1533\">prisión de quince o más años</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-146,18-177\">🎯 2 preguntas</mark></p><p>A los quince, cuando la pena máxima señalada por la ley <mark class=\"m-personalizado\">sea <mark class=\"m-resp r-ia\" data-q=\"18-ia-1534\">inhabilitación por más de diez años, o prisión por más de diez y menos de quince años</mark>.</mark></p><p>A los diez, cuando la pena máxima señalada por la ley sea <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1535\">prisión o inhabilitación por más de cinco años y que no exceda de diez</mark>.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-3\">🎯 1 pregunta</mark></p><p><mark class=\"m-plazo\">A los cinco, los</mark> <mark class=\"m-personalizado\">demás</mark> delitos, excepto los <mark class=\"m-personalizado\">delitos leves y los delitos de injurias y calumnias,</mark> que <mark class=\"m-personalizado\">prescriben</mark> <mark class=\"m-plazo\"><mark class=\"m-resp r-ia\" data-q=\"18-ia-1536\">al año</mark>.</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">Cuando la <u class=\"m-clave\">pena</u></mark> señalada por la <span class=\"ex-plg\"><span class=\"ex-plg-t\">ley fuere <mark class=\"m-destacable\">compuesta,</mark> <mark class=\"m-accion\">se estará,</mark> para <mark class=\"m-personalizado\">la aplicación de las reglas</mark> comprendidas en este artículo, <mark class=\"m-personalizado\">a la que exija</mark> <mark class=\"m-autoridad\">mayor tiempo para la prescripción.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1537\">🎯 1 pregunta</mark></p><p><b>4.</b> En los supuestos de <mark class=\"m-personalizado\">concurso de infracciones o de infracciones conexas,</mark> el plazo de prescripción <mark class=\"m-accion\">será</mark> el que corresponda al <mark class=\"m-personalizado\">delito más grave.</mark>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1539\">🎯 1 pregunta</mark></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>▦</i>PRESCRIPCIÓN DE LOS DELITOS · pena máxima señalada por la ley (cuadro del temario · art. 131)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Prescriben</span><span>Pena máxima señalada por la ley</span></div><div class=\"vt-hoja\"><span class=\"vt-p n\">20 años</span><div class=\"vt-t\">Prisión de <mark class=\"m-plazo\">quince o más años</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">15 años</span><div class=\"vt-t\">Inhabilitación por <mark class=\"m-plazo\">más de diez años</mark> · prisión por <mark class=\"m-plazo\">más de diez y menos de quince años</mark>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p v\">10 años</span><div class=\"vt-t\">Prisión o inhabilitación por <mark class=\"m-plazo\">más de cinco años</mark> y que <u class=\"m-clave\">no exceda de diez</u>.</div></div><div class=\"vt-hoja\"><span class=\"vt-p c\">5 años</span><div class=\"vt-t\">Los demás delitos.</div></div><div class=\"vt-hoja\"><span class=\"vt-p n\">1 año</span><div class=\"vt-t\">Delitos leves y los delitos de injurias y calumnias.</div></div><div class=\"vt-nodo\"><div class=\"vt-et o\">NO PRESCRIBEN</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Delitos de lesa humanidad y de genocidio y los delitos contra las personas y bienes protegidos en caso de conflicto armado, <u class=\"m-clave\">salvo</u> los castigados en el art. 614: no prescribirán <u class=\"m-clave\">en ningún caso</u>.</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Tampoco prescribirán los delitos de terrorismo, si hubieren causado la <mark class=\"m-plazo\">muerte de una</mark> persona.</div></div></div></div></div></div><div class=\"trampa\"><b>⚠ Cifras que se confunden</b><p><em><u class=\"m-clave\">Prescripción</u> de <mark class=\"m-personalizado\">los delitos</mark> (art. 131)</em><strong>20 <mark class=\"m-plazo\">años</mark> (<mark class=\"m-personalizado\">prisión</mark> de 15 o más) · 15 (<u class=\"m-clave\">inhabilitación</u> más de 10, o <mark class=\"m-personalizado\">prisión</mark> más de 10 y <u class=\"m-clave\">menos</u> de 15) · 10 (más de 5 y <mark class=\"m-personalizado\">hasta</mark> 10) · 5 (los <mark class=\"m-personalizado\">demás</mark>) · 1 año (<mark class=\"m-personalizado\">delitos leves</mark>, injurias y calumnias)</strong> — <u class=\"m-clave\">no</u> 10 <mark class=\"m-plazo\">años</mark> para <mark class=\"m-personalizado\">prisión</mark> de 15 o más · <u class=\"m-clave\">no</u> 3 <mark class=\"m-plazo\">años</mark> para los <mark class=\"m-personalizado\">demás</mark> · <u class=\"m-clave\">no</u> 5 <mark class=\"m-plazo\">años</mark> en injurias y calumnias</p>"],["Artículo 136 <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><b>1.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los condenados que hayan extinguido su responsabilidad penal tienen derecho</span></span> a obtener del <mark class=\"m-autoridad\">Ministerio</mark> de Justicia, de oficio o a instancia de parte, la cancelación de sus antecedentes penales, cuando hayan transcurrido sin haber vuelto a delinquir los siguientes plazos: <mark class=\"m-resp ex-q\" data-q=\"18-40\">🎯 1 pregunta</mark></p><p style=\"margin-left:18px\"><b>a)</b> Seis meses para las <mark class=\"m-resp r-ia\" data-q=\"18-ia-1551\">penas leves</mark>.</p><p style=\"margin-left:18px\"><b>b)</b> Dos años para las <mark class=\"m-resp r-ia\" data-q=\"18-ia-1552\">penas que no excedan de doce meses y las impuestas por delitos imprudentes</mark>.</p><p style=\"margin-left:18px\"><b>d)</b> Cinco años para las <mark class=\"m-resp r-ia\" data-q=\"18-ia-1553\">restantes penas menos graves iguales o superiores a tres años</mark>.</p><p style=\"margin-left:18px\"><b>e)</b> Diez años para las <mark class=\"m-resp r-ia\" data-q=\"18-ia-1554\">penas graves</mark>.</p><p><b>3.</b> <mark class=\"m-personalizado\">Las penas</mark> impuestas <mark class=\"m-personalizado\">a las</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-destacable\">jurídicas</mark> y las <mark class=\"m-personalizado\">consecuencias accesorias</mark> del artículo 129 <mark class=\"m-accion\">se cancelarán</mark> <mark class=\"m-destacable\">en el plazo que corresponda, de acuerdo con la regla prevista en el</mark> <mark class=\"m-personalizado\">apartado 1 de este artículo, salvo que se hubiese acordado la disolución o la prohibición definitiva de actividades. En estos casos,</mark> <mark class=\"m-accion\">se cancelarán</mark> <mark class=\"m-personalizado\">las anotaciones transcurridos cincuenta años</mark> <mark class=\"m-plazo\">computados desde el día siguiente a la firmeza de la sentencia.</mark> <mark class=\"m-resp ex-q\" data-q=\"18-87,18-ia-1555\">🎯 2 preguntas</mark></p><p><b><mark class=\"m-plazo\">4.</mark></b> <mark class=\"m-plazo\">Las inscripciones de antecedentes penales en</mark> las distintas secciones <span class=\"ex-plg\"><span class=\"ex-plg-t\">del <mark class=\"m-autoridad\">Registro Central de</mark> Penados y Rebeldes <mark class=\"m-accion\">no serán</mark> públicas. Durante su vigencia solo <mark class=\"m-accion\">se emitirán</mark> certificaciones con <mark class=\"m-personalizado\">las limitaciones</mark> y <mark class=\"m-personalizado\">garantías</mark> previstas en sus <mark class=\"m-personalizado\">normas específicas</mark> y en los casos establecidos <mark class=\"m-personalizado\">por la ley. En todo caso,</mark> <mark class=\"m-accion\">se librarán</mark> las que <mark class=\"m-personalizado\">soliciten los</mark> <mark class=\"m-autoridad\">jueces o tribunales,</mark> <mark class=\"m-personalizado\">se refieran o no a inscripciones canceladas,</mark> haciendo constar expresamente esta última circunstancia.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1556\">🎯 1 pregunta</mark></p><p><b>5.</b> En los casos <u class=\"m-clave\">en</u> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que, <mark class=\"m-personalizado\"><u class=\"m-clave\">a pesar</u> de cumplirse los requisitos</mark> establecidos en este artículo <mark class=\"m-personalizado\"><u class=\"m-clave\">para</u> la cancelación,</mark> ésta <mark class=\"m-personalizado\">no se haya producido,</mark> <mark class=\"m-autoridad\">el juez o tribunal,</mark> acreditadas tales circunstancias, <mark class=\"m-accion\">no tendrá</mark> <mark class=\"m-personalizado\">en cuenta dichos antecedentes.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"18-ia-1557\">🎯 1 pregunta</mark></p></div></div><div class=\"trampa\"><b>⚠ Cifras que se confunden</b><p><em>Cancelación de antecedentes penales (art. 136.1)</em><strong>6 meses (<mark class=\"m-destacable\">leves</mark>) · 2 <mark class=\"m-plazo\">años</mark> (<mark class=\"m-personalizado\">hasta</mark> 12 meses y <mark class=\"m-personalizado\">delitos</mark> <mark class=\"m-personalizado\">imprudentes</mark>) · 3 <mark class=\"m-plazo\">años</mark> (<u class=\"m-clave\">menos</u> <mark class=\"m-destacable\">graves</mark> < 3 años) · 5 años (menos graves ≥ 3 años) · 10 años (graves) · 50 años si hubo disolución o prohibición definitiva (apdo. 3)</strong> — <u class=\"m-clave\">no</u> 1 año para las <mark class=\"m-destacable\">leves</mark> · <u class=\"m-clave\">no</u> 20 <mark class=\"m-plazo\">años</mark> en la <mark class=\"m-personalizado\">disolución</mark> · <u class=\"m-clave\">no</u> 5 <mark class=\"m-plazo\">años</mark> para las <mark class=\"m-destacable\">graves</mark></p>"]];
